  id, name, manufacturer, category, description, recognition_hints, first_flight, max_speed_kmh, length_m, wingspan_m, height_m, range_km, ceiling_m, service_entry, retirement, country_of_origin, engines, units_built, rarity, image_url, image_author, image_license, image_license_url, image_source_url, wikidata_id, enwiki_title, aliases, wikipedia_url, sources, verified
) VALUES
  -- MiG-31 (Q150050)
  ('mikoyan-mig-31', 'MiG-31', 'Mikoyan-Gourevitch / Sokol', 'militaire', 'Mikoyan-Gourevitch MiG-31 (code OTAN : « Foxhound ») est un intercepteur d''origine soviétique (actuellement russe). Il est dérivé du célèbre MiG-25 Foxbat, dont il conserve l''allure générale et les performances élevées, mais en diffère notamment par la présence d''un second membre d''équipage et d''un radar à capacité « look-down/shoot-down » (détection et tir sur des cibles volant à une altitude inférieure).', NULL, '1975-09-16', NULL, 22.69, 13.46, 6.15, 3300, 20600, '1981-05-06', NULL, NULL, 'Soloviev D-30', 519, 3, 'https://upload.wikimedia.org/wikipedia/commons/c/c3/MiG-31_Pichugin-1.jpg', 'Dmitriy Pichugin', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:MiG-31_Pichugin-1.jpg', 'Q150050', 'Mikoyan MiG-31', ARRAY['mikoyan mig-31', 'mig-31', 'foxhound', 'mikoyan-gurevich mig-31 foxhound', 'mikoyan-gurevich mig-31'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-31', '{}'::jsonb, true),
  -- Mikoyan-Gourevitch MiG-25 (Q199570)
  ('mikoyan-gurevich-mig-25', 'Mikoyan-Gourevitch MiG-25', 'Mikoyan-Gourevitch / Sokol', 'militaire', 'Le Mikoyan-Gourevitch MiG-25 (en russe : Микоян и Гуревич МиГ-25) est un avion d''interception et de reconnaissance soviétique, connu sous le nom de code OTAN « Foxbat ». Avec le MiG-31, et le SR-71, il est un des seuls avions de combat capables d''atteindre une vitesse de Mach 3 à avoir été mis en service dans le monde.', NULL, '1964-03-05', NULL, 19.75, 14.01, 6.1, NULL, 20700, '1970-01-01', NULL, 'Union soviétique', 'Toumanski R-15', 1190, 3, 'https://upload.wikimedia.org/wikipedia/commons/a/a4/MiG-25RBS_Pichugin-1.jpg', 'Dmitriy Pichugin', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:MiG-25RBS_Pichugin-1.jpg', 'Q199570', 'Mikoyan-Gurevich MiG-25', ARRAY['mikoyan-gurevich mig-25', 'mikoyan-gourevitch mig-25', 'mig-25 foxbat', 'mikoyan mig-25', 'foxbat', 'mig-25'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-25', '{}'::jsonb, true),
  -- Mikoyan-Gurevich MiG-23 (Q155679)
  ('mikoyan-gurevich-mig-23', 'Mikoyan-Gurevich MiG-23', 'Mikoyan-Gourevitch', 'militaire', 'Le Mikoyan-Gourevitch MiG-23 (Микоян и Гуревич МиГ-23 en russe, code OTAN Flogger) est un avion de chasse soviétique à géométrie variable, capable d''opérer depuis des aérodromes petits et mal entretenus. Conçu par Mikoyan-Gourevitch, c''est le premier chasseur soviétique capable de repérer et d''engager des cibles volant plus bas que lui, et hors de portée visuelle. Une version spécialisée dans l''attaque au sol a également été réalisée.', NULL, '1967-06-10', NULL, 16.7, 13.97, 4.82, NULL, 18500, '1970-01-01', NULL, 'Union soviétique', NULL, 5047, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/MiG-23-red12.jpg/1280px-MiG-23-red12.jpg', 'US military', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:MiG-23-red12.jpg', 'Q155679', 'Mikoyan-Gurevich MiG-23', ARRAY['mikoyan-gurevich mig-23', 'flogger', 'mikoyan-gurevich flogger', 'mig-23', 'mig 23', 'mikoyan-gourevitch mig-23'], 'https://fr.wikipedia.org/wiki/Mikoyan-Gourevitch_MiG-23', '{}'::jsonb, true),
  -- Su-57 (Q194455)
  ('sukhoi-su-57', 'Su-57', 'Komsomolsk-on-Amur Aircraft Production Association', 'militaire', 'Le Soukhoï Su-57 (en russe : Сухой Су-57, Code OTAN : Felon, depuis septembre 2019) est un avion de combat polyvalent furtif russe de cinquième génération. Une version issue d''une coopération indo-russe développée par Soukhoï aurait dû voir le jour sous la désignation HAL FGFA. L''appellation « PAK-FA » (en russe : Перспективный Авиационный Комплекс Фронтовой Авиации) peut être traduite en français par « Futur Système aéronautique de l''aviation du front », mais a été abandonnée.', NULL, '2010-01-29', NULL, 19.8, 14, 6.06, 5500, 20000, '2018-01-01', NULL, 'Russie', 'Saturn AL-41', 10, 5, 'https://upload.wikimedia.org/wikipedia/commons/9/93/Sukhoi_T-50_in_2011_%284%29.jpg', 'Dmitry Zherdin', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Sukhoi_T-50_in_2011_(4).jpg', 'Q194455', 'Sukhoi Su-57', ARRAY['sukhoi su-57', 'su-57', 'cuidado con los peruanos', 'sukhoi pak fa', 'sukhoi t-50', 'pak fa', 't-50 aircraft', 'sukhoi 57', 'su57', 'felon', 'soukhoï pak-fa', 't-50', 'soukhoï t-50'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-57', '{}'::jsonb, true),
  -- Ilyushin Il-76 (Q142549)
  ('ilyushin-il-76', 'Ilyushin Il-76', 'Iliochine / Association de construction aéronautique de Tachkent', 'militaire', 'L''Iliouchine II-76 est un avion de transport militaire moyen/long courrier quadriréacteur à double flux conçu en Union soviétique à partir de 1967, mais dont le programme a débuté au début des années 1960. Sa désignation OTAN est Candid. Il existe également en version avion ravitailleur nommée Iliouchine Il-78 (code OTAN : Midas) et en version système de détection et de commandement aéroporté, nommée Iliouchine A-50 (code OTAN : Mainstay).', NULL, '1971-03-25', NULL, 46.59, 50.5, NULL, NULL, NULL, '1974-01-01', NULL, 'Union soviétique', 'Aviadvigatel PS-90', 950, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Ilyushin_IL-76MD_-_Ukrainian_Air_Force_-_76683_%2848367735331_cropped%29.jpg/1280px-Ilyushin_IL-76MD_-_Ukrainian_Air_Force_-_76683_%2848367735331_cropped%29.jpg', 'Steve Lynes from Sandshurst, United Kingdom', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:Ilyushin_IL-76MD_-_Ukrainian_Air_Force_-_76683_(48367735331_cropped).jpg', 'Q142549', 'Ilyushin Il-76', ARRAY['ilyushin il-76', 'candid', 'il-76', 'iliouchine il-76 candid', 'illiouchine il-76 candid', 'ilyushin il-76 candid'], 'https://fr.wikipedia.org/wiki/Iliouchine_Il-76', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://www.soldiering.ru/avia/airplane/il76.php"]}'::jsonb, true),
  -- Mil Mi-8 (Q155635)
  ('mil-mi-8', 'Mil Mi-8', 'Mil / Kazan Helicopter', 'autre', 'Le Mil Mi-8 (en russe : « Ми-8 »), désigné par l''OTAN « Hip » (« Haze » pour sa version marine), est un hélicoptère polyvalent conçu et fabriqué en URSS (plus tard en Russie) par Mil à Kazan et Oulan-Oudé. Son premier vol a lieu en juin 1961. Il remplace le Mil Mi-4, équipé d''un moteur à pistons. La version Mi-9 est un PC volant, tandis que la version marine Mi-14 (Code OTAN : « Haze ») se distingue par son fuselage en forme de coque de bateau.', NULL, '1961-07-07', NULL, 18.17, NULL, 5.65, NULL, 4500, '1965-01-01', NULL, 'Union soviétique', 'Klimov TV2-117', 12000, 1, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/Mi-8-JH01.jpg/1280px-Mi-8-JH01.jpg', 'Jan Hrdonka', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Mi-8-JH01.jpg', 'Q155635', 'Mil Mi-8', ARRAY['mil mi-8', 'hip', 'mil hip', 'h-40', 'mil mi-18', 'mil mi-9', 'mil-8', 'mi-8'], 'https://fr.wikipedia.org/wiki/Mil_Mi-8', '{"units_built":["http://www.aex.ru/news/2014/5/23/120575/"]}'::jsonb, true),
  -- Lockheed SR-71 Blackbird (Q190114)
  ('lockheed-sr-71-blackbird', 'Lockheed SR-71 Blackbird', 'Skunk Works', 'militaire', 'Le Lockheed SR-71 Blackbird (Merle) est un avion de reconnaissance à long rayon d''action et à haute altitude, construit par Lockheed Corporation pour l''armée de l''air américaine, qui l''utilisa principalement de 1968 à 1990. Il a été développé à partir de l''avion-espion Lockheed A-12 Oxcart.', NULL, '1964-12-22', 3445, 32.74, 16.94, 5.64, 2700, 25908, '1966-01-07', '1999-10-09', 'États-Unis', 'Pratt & Whitney J58', 29, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/SR-71A_in_flight_near_Beale_AFB_1988.JPEG/1280px-SR-71A_in_flight_near_Beale_AFB_1988.JPEG', 'TSgt. Michael Haggerty, USAF', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:SR-71A_in_flight_near_Beale_AFB_1988.JPEG', 'Q190114', 'Lockheed SR-71 Blackbird', ARRAY['lockheed sr-71 blackbird', 'blackbird', 'sr71 blackbird', 'rs-71 blackbird', 'sr-71 blackbird', 'lockheed sr-71', 'sr 71'], 'https://fr.wikipedia.org/wiki/Lockheed_SR-71_Blackbird', '{"first_flight":["https://www.smithsonianmag.com/smithsonian-institution/why-sr-71-blackbird-epitome-cold-war-spycraft-180953402/","https://www.lockheedmartin.com/en-us/news/features/history/blackbird.html","https://appel.nasa.gov/wp-content/uploads/2013/03/Blackbird-FAQ.pdf"],"max_speed_kmh":["https://www.nasa.gov/wp-content/uploads/2021/09/495839main_fs-030_sr-71.pdf","https://www.sr-71.org/blackbird/manual/5/5-9.php","https://aerotoolbox.com/airspeed-conversions/"],"length_m":["https://airandspace.si.edu/collection-objects/lockheed-sr-71-blackbird/nasm_A19920072000"],"wingspan_m":["https://airandspace.si.edu/collection-objects/lockheed-sr-71-blackbird/nasm_A19920072000"],"height_m":["https://airandspace.si.edu/collection-objects/lockheed-sr-71-blackbird/nasm_A19920072000"],"range_km":["https://pacificcoastairmuseum.org/aircraft/sr-71-blackbird-nose/"],"ceiling_m":["https://www.nasa.gov/centers/armstrong/news/FactSheets/FS-030-DFRC.html"],"units_