  -- Douglas A-4 Skyhawk (Q334759)
  ('douglas-a-4-skyhawk', 'Douglas A-4 Skyhawk', 'Douglas / McDonnell Douglas', 'collection', 'Le Douglas A-4 Skyhawk est un avion d''attaque (surnommé « scooter ») léger construit par les États-Unis, initialement destiné à être embarqué à bord de porte-avions. Robuste, efficace et peu coûteux, cet avion rencontre un important succès commercial avec près de 3 000 exemplaires construits pour une dizaine de pays utilisateurs.', NULL, '1954-06-22', NULL, 12.22, 8.5, 5, 3220, 14000, '1956-10-01', '1998-01-01', 'États-Unis', 'General Electric F404 / J52', 2960, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/Last_bulit_A-4_Skyhawk_in_flight_in_February_1979.jpg/1280px-Last_bulit_A-4_Skyhawk_in_flight_in_February_1979.jpg', 'U.S. Navy', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Last_bulit_A-4_Skyhawk_in_flight_in_February_1979.jpg', 'Q334759', 'Douglas A-4 Skyhawk', ARRAY['douglas a-4 skyhawk', 'mcdonnell douglas a-4', 'douglas a4d', 'attack design 4', 'a4d skyhawk', 'mcdonnell douglas a-4 skyhawk', 'a4', 'douglas a4d skyhawk', 'skyhawk', 'a4d', 'douglas attack design 4', 'douglas a-4', 'douglas skyhawk', 'a-4', '"skyhawk"', 'a-4 skyhawk'], 'https://fr.wikipedia.org/wiki/Douglas_A-4_Skyhawk', '{}'::jsonb, true),
  -- Bell P-39 Airacobra (Q385778)
  ('bell-p-39-airacobra', 'Bell P-39 Airacobra', 'Bell', 'collection', 'Le P-39 Airacobra est un chasseur américain de la Seconde Guerre mondiale construit par Bell Aircraft Corporation. Cet avion de conception peu orthodoxe se distinguait par son moteur peu accessible situé au milieu du fuselage et entraînant une hélice à l''avant, par le biais d''un long arbre de transmission passant entre les jambes du pilote.', NULL, '1938-04-06', NULL, 9.19, 10.36, 3.78, NULL, NULL, '1941-01-01', NULL, 'États-Unis', NULL, 9584, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Bell_P-39Q_Airacobra_USAF.jpg/1280px-Bell_P-39Q_Airacobra_USAF.jpg', 'The original uploader was Signaleer at English Wikipedia.', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Bell_P-39Q_Airacobra_USAF.jpg', 'Q385778', 'Bell P-39 Airacobra', ARRAY['bell p-39 airacobra', 'p-39 aircraft', 'bell airacobra', 'airacobra', 'p-39 airacobra', 'p-400 airacobra', 'bell p-400', 'bell p-400 airacobra', 'bell caribou', 'bell model 11', 'bell model 12', 'bell model 13', 'bell model 14', 'bell model 15', 'bell model 23', 'bell model 26', 'bell p-45', 'p-45 airacobra', 'p-39', 'p-45', 'p-400', 'bell model 21', 'bell model 3', 'bell model 4', 'bell model 6'], 'https://fr.wikipedia.org/wiki/Bell_P-39_Airacobra', '{}'::jsonb, true),
  -- Mitsubishi F-2 (Q209480)
  ('mitsubishi-f-2', 'Mitsubishi F-2', 'Mitsubishi', 'militaire', 'Le Mitsubishi F-2 est un avion de chasse multirôle japonais construit par Mitsubishi. Il est basé sur le F-16 de General Dynamics (devenu depuis 1993 Lockheed Martin), compagnie qui est un important sous-traitant de Mitsubishi sur le F-2. Il est parfois surnommé Vipère Zéro par ses pilotes.', NULL, '1995-10-07', NULL, NULL, NULL, NULL, NULL, NULL, '2000-09-25', NULL, 'États-Unis', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Mitsubishi_F-2_at_Guam_%28Cropped%29.jpg/1280px-Mitsubishi_F-2_at_Guam_%28Cropped%29.jpg', 'Marine Cpl. Ashleigh Bryant', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Mitsubishi_F-2_at_Guam_(Cropped).jpg', 'Q209480', 'Mitsubishi F-2', ARRAY['mitsubishi f-2', 'fs-x', 'fsx', 'viper zero', 'f-2'], 'https://fr.wikipedia.org/wiki/Mitsubishi_F-2', '{}'::jsonb, true),
  -- SEPECAT Jaguar (Q223237)
  ('sepecat-jaguar', 'SEPECAT Jaguar', 'Société anonyme des ateliers d’aviation Louis Breguet / British Aircraft Corporation', 'militaire', 'Le SEPECAT Jaguar est un avion militaire de conception franco-britannique dont la version monoplace est destinée à l''attaque au sol et la version biplace à l''entraînement avancé. Mis en service en 1973, il a été construit à un peu plus de 600 exemplaires utilisés par six pays, dont l''Inde qui l''a construit sous licence.', NULL, '1968-09-08', NULL, 15.52, 8.49, NULL, 850, NULL, '1973-01-01', NULL, 'France / Royaume-Uni', NULL, 543, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/French_Jaguar_A_of_EC_1-7_Provence_in_flight_over_the_Adriatic_Sea%2C_8_April_2003_%28DF-SD-05-05511%29.jpg/1280px-French_Jaguar_A_of_EC_1-7_Provence_in_flight_over_the_Adriatic_Sea%2C_8_April_2003_%28DF-SD-05-05511%29.jpg', 'TSGT Mike Buytas, USAF photo DF-SD-05-05511', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:French_Jaguar_A_of_EC_1-7_Provence_in_flight_over_the_Adriatic_Sea,_8_April_2003_(DF-SD-05-05511).jpg', 'Q223237', 'SEPECAT Jaguar', ARRAY['sepecat jaguar', 'jaguar aircraft', 'jaguar attack aircraft', 'jaguar'], 'https://fr.wikipedia.org/wiki/SEPECAT_Jaguar', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Iliouchine Il-14 (Q275031)
  ('ilyushin-il-14', 'Iliouchine Il-14', 'Iliochine / Avia', 'collection', 'L''Iliouchine Il-14 (Code OTAN : « Crate ») est un avion de transport civil et militaire soviétique mis en service en 1954. Construit par l''usine d''aviation de Tachkent, il fut également produit en RDA, en Tchécoslovaquie sous la désignation Avia 14, et en Chine sous la désignation Y-6.', NULL, '1950-10-01', NULL, 22.3, 31.7, 7.8, NULL, 6500, '1954-11-30', '2005-01-01', 'Union soviétique', 'ASh-82T', 1348, 3, 'https://upload.wikimedia.org/wikipedia/commons/9/92/%D0%A1%D0%A1%D0%A1%D0%A0-91612_IL14_Private_-_Penguin_livery_-_by_name_Mikhail_Farikh_-_UUTO_%2833251180091%29_%282%29.jpg', 'Papas Dos from Moscow, Russia', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:%D0%A1%D0%A1%D0%A1%D0%A0-91612_IL14_Private_-_Penguin_livery_-_by_name_Mikhail_Farikh_-_UUTO_(33251180091)_(2).jpg', 'Q275031', 'Ilyushin Il-14', ARRAY['ilyushin il-14', 'iliouchine il-14', 'avia 14', 'il14', 'y-6', 'ilyushin il-14 crate', 'crate', 'il-14'], 'https://fr.wikipedia.org/wiki/Iliouchine_Il-14', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Antonov An-148 (Q607355)
  ('antonov-an-148', 'Antonov An-148', 'Aviant / Voronezh Aircraft Production Association', 'ligne', 'L''An-148 et l''An-158 sont des avions de ligne régionaux ukrainiens. L''An 158 est une version rallongée de l''An-148, sa capacité passant de 75 à 100 passagers.', NULL, '2004-12-17', NULL, NULL, NULL, NULL, NULL, NULL, '2009-06-02', NULL, NULL, NULL, 49, 5, 'https://upload.wikimedia.org/wikipedia/commons/1/12/Antonov--148_2.jpg', 'Dmitry A. Mottl', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Antonov--148_2.jpg', 'Q607355', 'Antonov An-148', ARRAY['antonov an-148'], 'https://fr.wikipedia.org/wiki/Antonov_An-148', '{"units_built":["http://russianplanes.net/planelist/Antonov/An-148"]}'::jsonb, true),
  -- Boeing P-8 Poseidon (Q611401)
  ('boeing-p-8-poseidon', 'Boeing P-8 Poseidon', 'Boeing Integrated Defense Systems', 'militaire', 'Le Boeing P-8A Poseidon, aussi désigné P-8 MMA pour Multimission Maritime Aircraft, est un avion de patrouille maritime et de lutte anti-sous-marine américain entré en service fin 2013. Il est dérivé de l''avion de ligne Boeing 737.', NULL, '2009-04-25', NULL, 39.47, 37.64, 12.83, NULL, NULL, '2013-11-01', NULL, 'États-Unis', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/P-8A_Poseidon_VX-20_Squadron.jpg/1280px-P-8A_Poseidon_VX-20_Squadron.jpg', 'Greg L. Davis', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:P-8A_Poseidon_VX-20_Squadron.jpg', 'Q611401', 'Boeing P-8 Poseidon', ARRAY['boeing p-8 poseidon', 'boeing p8', 'poseidon', 'p8 poseidon', 'mma', 'poseidon patrol aircraft', 'p-8i neptune', 'multimission maritime aircraft'], 'https://fr.wikipedia.org/wiki/Boeing_P-8_Poseidon', '{"length_m":["https://www.wikidata.org/wiki/Q746368"],"wingspan_m":["https://www.wikidata.org/wiki/Q746368"]}'::jsonb, true),
  -- Chengdu J-10 (Q635779)
  ('chengdu-j-10', 'Chengdu J-10', 'Chengdu Aircraft Corporation', 'militaire', 'Le J-10 (歼-10 jiān 10 ou Jianji-10) est un avion multirôle tout-temps de quatrième génération construit par la firme Chengdu Aircraft Corporation établie à Chengdu, en Chine pour la force aérienne chinoise. Il est connu en Occident sous le nom « Vigorous Dragon ». Il est entré en service en 2003 dans la force aérienne chinoise et existe en plusieurs versions.', NULL, '1998-03-23', NULL, NULL, NULL, NULL, NULL, NULL, '2005-01-01', NULL, 'République populaire de Chine', NULL, 468, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/PLAAF_J-10A_-_1.jpg/1280px-PLAAF_J-10A_-_1.jpg', '中華民國國防部', 'Attribution', NULL, 'https://commons.wikimedia.org/wiki/File:PLAAF_J-10A_-_1.jpg', 'Q635779', 'Chengdu J-10', ARRAY['chengdu j-10', 'j10', 'firebird', 'chengdu f-10 vanguard', 'f-10 vanguard', 'vanguard', 'vigorous dragon', 'f10', 'j-10'], 'https://fr.wikipedia.org/wiki/Chengdu_J-10', '{"units_built":["https://www.mod.go.jp/j/publication/wp/wp2020/pdf/R02010202.pdf","http://www.sinodefence.com/airforce/fighter/j10deployment.asp"]}'::jsonb, true),
  -- Fokker F28 Fellowship (Q725319)
  ('fokker-f28-fellowship', 'Fokker F28 Fellowship', 'Fokker', 'ligne', 'Le Fokker F28 Fellowship est un avion de transport régional à réaction court-courrier, conçu et construit par le constructeur aéronautique néerlandais Fokker. Annoncée par Fokker en avril 1962, la production a été le fruit d''une collaboration entre un certain nombre de sociétés européennes, à savoir Fokker, les Allemands MBB et Fokker-VFW et le Britannique Short Brothers.', NULL, '1967-05-09', NULL, 27.4, 23.58, 8.5, NULL, 11000, '1969-03-28', NULL, 'Pays-Bas', 'Rolls-Royce Spey', 241, 4, 'https://upload.wikimedia.org/wikipedia/commons/8/8b/Scandinavian_Airlines_F-28-4000.jpg', 'Torsten Maiwald', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Scandinavian_Airlines_F-28-4000.jpg', 'Q725319', 'Fokker F28 Fellowship', ARRAY['fokker f28 fellowship', 'fellowship aircraft', 'f28', 'fellowship', 'f28 aircraft', 'fokker fellowship', 'f28 fellowship', 'f28 fellowship 3000', 'f-28'], 'https://fr.wikipedia.org/wiki/Fokker_F28', '{}'::jsonb, true),
  -- JF-17 Thunder (Q744253)
  ('cac-pac-jf-17-thunder', 'JF-17 Thunder', 'Chengdu Aircraft Corporation / Pakistan Aeronautical Complex', 'militaire', 'Le JF-17 Thunder (en urdu : تھنڈر), également nommé Chengdu FC-1 Xiaolong (chinois simplifié : 枭龙 ; pinyin : xiāo lóng ; litt. « Dragon brave », anglais : Fierce Dragon), est un avion de combat multirôle, monoréacteur léger développé en coopération entre Chengdu Aircraft Industries Corporation (CAC) (république populaire de Chine), l''Armée de l''air pakistanaise et l''industrie aéronautique pakistanaise.', NULL, '2003-08-25', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'République populaire de Chine', NULL, 86, 4, 'https://upload.wikimedia.org/wikipedia/commons/a/a8/Pakistan_JF-17_Thunder%2C_Pakistan_-_Air_Force_JP7136023.jpg', 'Aldo Bidini', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Pakistan_JF-17_Thunder,_Pakistan_-_Air_Force_JP7136023.jpg', 'Q744253', 'CAC/PAC JF-17 Thunder', ARRAY['cac/pac jf-17 thunder', 'jf-17 thunder', 'fighter china no.1', 'fc-1', 'fc1', 'joint fighter-17 thunder', 'jf-17', 'chengdu fc-1', 'chengdu fc-1 xiaolong'], 'https://fr.wikipedia.org/wiki/Chengdu_JF-17_Thunder', '{}'::jsonb, true),
  -- Su-9 (Q746313)
  ('sukhoi-su-9', 'Su-9', 'Soukhoï / Novosibirsk Aircraft Production Association', 'collection', 'Le Soukhoï Su-9 (code OTAN Fishpot) est un avion de chasse à aile delta conçu par l''URSS pendant les années 1950. Il est très proche du Soukhoï Su-7 qui dispose lui d''une aile en flèche. Une version améliorée avec un radar plus puissant fut désignée Su-11. Les différentes versions des Su-9 et Su-11 ont été construites à plus de 1 200 exemplaires, dont aucun n''a été exporté.', NULL, '1957-10-10', NULL, 17.37, 8.43, 4.88, NULL, NULL, '1959-01-01', '1981-01-01', 'Union soviétique', 'Lyulka AL-7', 1150, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Su-9B_VVS_museum.jpg/1280px-Su-9B_VVS_museum.jpg', 'Mike1979 Russia', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Su-9B_VVS_museum.jpg', 'Q746313', 'Sukhoi Su-9', ARRAY['sukhoi su-9', 'su-9', 'fishpot', 't-405', 'soukhoi su-9', 'soukhoï su-9'], 'https://fr.wikipedia.org/wiki/Soukho%C3%AF_Su-9', '{}'::jsonb, true),
  -- Ar 234 Blitz (Q157335)
  ('arado-ar-234-blitz', 'Ar 234 Blitz', 'Arado Flugzeugwerke GmbH', 'collection', 'L''Arado Ar 234 Blitz est le premier bombardier à réaction à entrer en service dans une force aérienne. Conçu dans les dernières années de la Seconde Guerre mondiale par le constructeur allemand Arado, il ne fut produit et utilisé qu''en petit nombre, presque exclusivement dans des missions de reconnaissance.', NULL, '1943-06-15', NULL, 12.64, 14.41, NULL, NULL, 10000, '1944-09-01', NULL, 'Allemagne', NULL, 244, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Arado_Ar_234_at_the_Steven_F._Udvar-Hazy_Center.JPG/1280px-Arado_Ar_234_at_the_Steven_F._Udvar-Hazy_Center.JPG', 'Nick-D', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Arado_Ar_234_at_the_Steven_F._Udvar-Hazy_Center.JPG', 'Q157335', 'Arado Ar 234 Blitz', ARRAY['arado ar 234', 'ar 234 blitz', 'arado ar 234 blitz', 'blitz bomber', 'blitz aircraft', 'ar234', 'ar 234', 'ar-234'], 'https://fr.wikipedia.org/wiki/Arado_Ar_234', '{}'::jsonb, true),
