  ('agusta-a129-mangusta', 'A129 Mangusta', 'Agusta / AgustaWestland', 'militaire', '129 Mangusta est un hélicoptère d''attaque léger italien. Performant, il est parfois comparé aux premières versions de l''AH-64 Apache américain.', NULL, '1983-09-11', NULL, 14.29, NULL, NULL, NULL, NULL, '1990-01-01', NULL, 'Italie', 'Rolls-Royce Gem', 66, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/AgustaA129_03.jpg/1280px-AgustaA129_03.jpg', 'Mike Lehmann', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:AgustaA129_03.jpg', 'Q398999', 'Agusta A129 Mangusta', ARRAY['a129 mangusta', 'agusta a129 mangusta', 'agusta a129', 'mangusta', 'ah-129', 'ah129', 'agustawestland aw129', 'agusta a 129 mangusta', 'agustawestland aw 129 mangusta', 'aw129 mangusta', 'aw 129 mangusta', 'agusta mangusta', 'a-129 mangusta', 'tai t-129 atak', 'a.129 mangusta'], 'https://fr.wikipedia.org/wiki/Agusta_A.129_Mangusta', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Mil Mi-2 (Q608997)
  ('mil-mi-2', 'Mil Mi-2', 'PZL-Świdnik', 'autre', 'Le Mil Mi-2, code OTAN : « Hoplite », est un petit hélicoptère de transport léger de conception soviétique, fabriqué par la société Mil au début des années 1960. Premier hélicoptère soviétique à être propulsé par des turbomoteurs, il peut accomplir des missions d''appui aérien rapproché quand il est armé de roquettes de 57 mm et d''un canon de 23 mm.', NULL, '1961-09-22', 209, 17.42, 14.5, 1.4, 580, 4193, '1965-01-01', NULL, 'Union soviétique', 'GTD-350', 5497, 2, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Krzesiny_106RB.JPG/1280px-Krzesiny_106RB.JPG', 'Radomil talk', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Krzesiny_106RB.JPG', 'Q608997', 'Mil Mi-2', ARRAY['mil mi-2', 'h-41', 'ht-41', 'wsk-swidnik mi-2', 'hoplite', 'mi-2'], 'https://fr.wikipedia.org/wiki/Mil_Mi-2', '{"max_speed_kmh":["https://www.wikidata.org/wiki/Q56645322"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"wingspan_m":["https://www.wikidata.org/wiki/Q56645322"],"height_m":["https://www.wikidata.org/wiki/Q56645322"],"range_km":["https://www.wikidata.org/wiki/Q56645322"],"ceiling_m":["https://www.wikidata.org/wiki/Q56645322"]}'::jsonb, true),
