  ('eurocopter-ec145', 'Eurocopter EC145', 'Airbus Helicopters / Kawasaki Heavy Industries', 'autre', 'Le MBB-Kawasaki BK117, renommé Eurocopter EC145 puis Airbus Helicopters H145 à la suite des changements de constructeurs, est un hélicoptère polyvalent biturbine destiné aux marchés civil, parapublic et militaire. Il est le résultat d''un développement conjoint de 1979 entre Messerschmitt-Bölkow-Blohm (MBB) et Kawasaki Heavy Industries (KHI).', NULL, '1999-06-12', NULL, NULL, NULL, NULL, NULL, NULL, '2002-01-01', NULL, NULL, 'Turbomeca Arriel 1E2', NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Zepper-BK_117-C2-%28EC145%29-SchweizerischeRettungsflugwacht.jpg/1280px-Zepper-BK_117-C2-%28EC145%29-SchweizerischeRettungsflugwacht.jpg', 'Matthias Zepper', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Zepper-BK_117-C2-(EC145)-SchweizerischeRettungsflugwacht.jpg', 'Q39679', 'Eurocopter EC145', ARRAY['airbus helicopters h145', 'eurocopter ec145', 'bk117c2', 'h-145', 'eurocopter ec 145', 'mbb/kawasaki bk 117 c-2', 'ec 145', 'ec145', 'airbus helicopters ec145', 'airbus h145', 'h145'], 'https://fr.wikipedia.org/wiki/Eurocopter_EC145', '{}'::jsonb, true),
