  -- Aérospatiale SA 330 Puma (Q794586)
  ('aerospatiale-sa-330-puma', 'Aérospatiale SA 330 Puma', 'Aérospatiale / Sud-Aviation', 'militaire', '330 Puma est un hélicoptère de transport moyen civil et militaire français. Conçu par Sud-Aviation et développé par l''Aérospatiale dans les années 1960, il a été construit en collaboration avec Westland Helicopters. À la création d''Eurocopter en 1990, cette société a poursuivi le développement, rebaptisant les versions militaires Cougar.', NULL, '1965-04-15', NULL, 14, NULL, 5.14, NULL, NULL, '1969-01-01', NULL, 'France', NULL, 697, 3, 'https://upload.wikimedia.org/wikipedia/commons/c/c6/Aerospatiale_SA_330B_Puma%2C_France_-_Army_JP7168956.jpg', 'Aldo Bidini', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Aerospatiale_SA_330B_Puma,_France_-_Army_JP7168956.jpg', 'Q794586', 'Aérospatiale SA 330 Puma', ARRAY['aérospatiale sa 330 puma', 'aérospatiale sa 330', 'aérospatiale puma', 'sud sa 330', 'eurocopter sa 330', 'puma', 'aerospatiale sa 330', 'aerospatiale puma', 'eurocopter puma', 'sa330', 'aerospatiale sa 330 puma', 'aerospatiale/westland sa.330 puma', 'sud aviation sa 330 puma', 'super puma', 'atlas tp-1 oryx', 'puma (helicoptere)', 'sa.330', 'hélicoptère puma', 'sa330 puma', 'puma (hélicoptère)', 'eurocopter as332 super puma', 'eurocopter sa330 puma'], 'https://fr.wikipedia.org/wiki/Sud-Aviation_SA330_Puma', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Aérospatiale SA 341 Gazelle (Q794595)
  ('aerospatiale-gazelle', 'Aérospatiale SA 341 Gazelle', 'Aérospatiale / Airbus Helicopters', 'autre', 'La Gazelle est un hélicoptère léger polyvalent de construction métallique conçu dans la deuxième moitié des années 1960 par Sud-Aviation et produit en série à partir du début des années 1970 par la Société nationale industrielle aérospatiale (SNIAS ou Aérospatiale) en collaboration avec Westland Helicopters (Royaume-Uni). L''appareil est décliné en deux versions commerciales principales (nomenclatures SA 341 et SA 342).', NULL, '1967-04-07', NULL, 11.97, NULL, 3.15, NULL, 5000, '1973-01-01', NULL, 'France', NULL, 1775, 3, 'https://upload.wikimedia.org/wikipedia/commons/2/2c/Gazelle_SA341F2.jpg', 'Eric Gaba (Sting - fr:Sting)', 'CC BY-SA 2.5', 'https://creativecommons.org/licenses/by-sa/2.5', 'https://commons.wikimedia.org/wiki/File:Gazelle_SA341F2.jpg', 'Q794595', 'Aérospatiale Gazelle', ARRAY['gazeller', 'aérospatiale sa 341 gazelle', 'aérospatiale gazelle', 'aerospatiale gazelle', 'gazelle helicopter', 'sud gazelle', 'sa 341 gazelle', 'sa 342 gazelle', 'sud aviation gazelle', 'westland gazelle', 'abhco gazelle', 'abhco', 'westland/aérospatiale gazelle', 'gazelle (helicoptere)', 'sa 341'], 'https://fr.wikipedia.org/wiki/Sud-Aviation_SA340/341/342_Gazelle', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
