  ('eurocopter-ec135', 'Eurocopter EC135', 'Airbus Helicopters', 'autre', 'L''Airbus Helicopters H135 (anciennement EC135) est un hélicoptère biturbine léger polyvalent produit par Airbus Helicopters.', NULL, '1994-02-01', NULL, NULL, NULL, NULL, NULL, NULL, '1996-07-31', NULL, 'Allemagne', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Eurocopter_EC_135_P2.jpg/1280px-Eurocopter_EC_135_P2.jpg', 'Stahlkocher', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Eurocopter_EC_135_P2.jpg', 'Q39654', 'Eurocopter EC135', ARRAY['ec135', 'eurocopter ec135', 'airbus h135', 'eurocopter ec 135', 'airbus helicopters h135', 'h135', 'ec 135', 'eurocopter ec-135', 'airbus ec135'], 'https://fr.wikipedia.org/wiki/Eurocopter_EC135', '{"first_flight":["https://www.youtube.com/watch?v=7rkCU9-bQlE&list=PL4nkr7pTOvLMjwIX3L6KUpcnY-mq-aR99&index=20"]}'::jsonb, true),
  -- AS365 Dauphin (Q39663)
  ('eurocopter-as365-dauphin', 'AS365 Dauphin', 'Airbus Helicopters', 'militaire', '365 Dauphin est un hélicoptère moyen polyvalent conçu à l''origine par la société française Sud-Aviation pour succéder à l''Alouette III. Il est ensuite développé par la Société nationale industrielle aérospatiale, qui a acquis Sud-Aviation. La division hélicoptère de l''Aérospatiale devient en 1990 la branche française d''Airbus Helicopters, et le Dauphin fait l''objet de développements civils et militaires.', NULL, '1975-01-24', NULL, 11.44, NULL, NULL, NULL, NULL, '1989-01-01', NULL, NULL, NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/AS-365N_Dauphin_2_of_The_Iceland_Coast_Guard.JPEG/1280px-AS-365N_Dauphin_2_of_The_Iceland_Coast_Guard.JPEG', 'SSGT ANTHONY W. LUSI, USAF', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:AS-365N_Dauphin_2_of_The_Iceland_Coast_Guard.JPEG', 'Q39663', 'Eurocopter AS365 Dauphin', ARRAY['dauphin 2', 'as365 dauphin', 'eurocopter as365 dauphin', 'as 365 dauphin 2', 'airbus helicopters as365 dauphin 2', 'eurocopter sa365/as365 dauphin', 'aérospatiale dauphin 2', 'sa365', 'dauphin ii', 'aerospatiale as365', 'sa 365', 'aerospatiale sa.365 dauphin 2', 'aerospatiale sa 365 dauphin 2', 'eurocopter as365', 'dauphin', 'eurocopter ec 155', 'harbin z.9'], 'https://fr.wikipedia.org/wiki/Sud-Aviation_SA365_Dauphin', '{"first_flight":["https://fly-news.es/aviacion-comercial/helicoptero/aduanas-recibe-ultimo-airbus-as365-dauphin/"],"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Alouette II (Q316815)
  ('aerospatiale-alouette-ii', 'Alouette II', 'Aérospatiale / Sud-Aviation', 'autre', 'L''Alouette II est un hélicoptère léger polyvalent produit sous diverses versions par le constructeur aéronautique français SNCASE, devenu en 1970 l''Aérospatiale, et dont le département hélicoptère a par la suite été intégré dans le groupe Eurocopter. C’est aussi le premier hélicoptère au monde certifié avec une turbine à gaz.', NULL, '1955-03-12', NULL, 9.66, NULL, 2.75, 565, 2300, '1957-05-02', NULL, 'France', NULL, 1300, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/SA318_%28cropped%29.jpg/1280px-SA318_%28cropped%29.jpg', 'Airwolfhound', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:SA318_(cropped).jpg', 'Q316815', 'Aérospatiale Alouette II', ARRAY['alouette ii', 'aérospatiale alouette ii', 'sud alouette ii', 'aerospatiale alouette ii', 'sud aviation alouette ii', 'se.3120 alouette', 'sncase se.3130 alouette ii', 'sncase se.3120 alouette', 'sa318b lama ii', 'sncase.se.3120 alouette', 'se.3130 alouette ii'], 'https://fr.wikipedia.org/wiki/SNCASE_SE.3130_Alouette_II', '{}'::jsonb, true),
  -- Ka-60 (Q618665)
  ('kamov-ka-60', 'Ka-60', 'Kamov', 'autre', 'Le Kamov Ka-60 Kasatka (« Orque ») est un hélicoptère de transport moyen d''origine russe.', NULL, '1998-12-24', NULL, 15.6, NULL, 4.2, NULL, 5100, NULL, NULL, NULL, NULL, 2, 5, 'https://upload.wikimedia.org/wikipedia/commons/0/0a/Ka-60-1.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Ka-60-1.jpg', 'Q618665', 'Kamov Ka-60', ARRAY['ka-60 family', 'ka-60', 'kamov ka-60', 'ka-60 helicopter', 'ka60', 'kamov ka-60 kasatka'], 'https://fr.wikipedia.org/wiki/Kamov_Ka-60_Kasatka', '{}'::jsonb, true),
  -- Bell 212 (Q698242)
  ('bell-212', 'Bell 212', 'Bell Textron', 'autre', 'Le Bell 212 est un hélicoptère biturbine du constructeur américain Bell Aircraft Corporation. Il a volé pour la première fois en 1968. C''est une version du Bell UH-1 Iroquois. En configuration cargo, il a une capacité de 6,23 m3 et peut emporter une charge de 2 268 kg.', NULL, '1965-04-29', NULL, 12.69, NULL, 4.4, 460, 5273, '1968-01-01', NULL, 'États-Unis', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Kachina-b212-N212KA-030909-02cr.jpg/1280px-Kachina-b212-N212KA-030909-02cr.jpg', 'own work', 'CC BY 2.5', 'https://creativecommons.org/licenses/by/2.5', 'https://commons.wikimedia.org/wiki/File:Kachina-b212-N212KA-030909-02cr.jpg', 'Q698242', 'Bell 212', ARRAY['bell 212', 'uh-1n', 'twin huey', '212', 'b212', 'bell model 212', 'model 212'], 'https://fr.wikipedia.org/wiki/Bell_212', '{}'::jsonb, true),
  -- Bell 412 (Q815688)
  ('bell-412', 'Bell 412', 'Bell Textron / Canada', 'autre', 'Le Bell 412 est un hélicoptère utilitaire fabriqué par Bell Aircraft Corporation. Il s''agit d''un développement réalisé à partir du Bell 212, la principale différence étant le rotor principal composé de quatre pales en matériau composite.', NULL, '1979-08-01', NULL, NULL, NULL, NULL, NULL, NULL, '1981-01-01', NULL, NULL, NULL, 869, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/N301FD.jpg/1280px-N301FD.jpg', 'Christian Valle', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:N301FD.jpg', 'Q815688', 'Bell 412', ARRAY['bell 412', 'b412', 'bell model 412', 'model 412', 'b 412', '412'], 'https://fr.wikipedia.org/wiki/Bell_412', '{}'::jsonb, true),
  -- Z-10 (Q1094179)
  ('changhe-z-10', 'Z-10', 'Changhe Aircraft Industries Corporation', 'militaire', 'Le WZ-10 (Wuzhuang Zhisheng-10) est un hélicoptère d''attaque produit par la République populaire de Chine. Il est conçu principalement pour des missions antichars, mais pourrait avoir des capacités air-air secondaires. Bien que l''on sache que le WZ-10 est une conception de troisième-génération, les évaluations de ses possibilités sont sujettes à caution. ] le considèrent comme étant inférieur aux conceptions occidentales contemporaines, telles que l''AH-64 Apache.', NULL, '2003-04-29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'République populaire de Chine', NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/0/0e/Changhe_Z-10.jpg', 'Shimin Gu', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Changhe_Z-10.jpg', 'Q1094179', 'Changhe Z-10', ARRAY['z-10', 'changhe z-10', 'caic wz-10', 'wz10', 'caic z-10', 'z10', 'pi li huo', 'fierce thunderbolt', 'changhe wz-10'], 'https://fr.wikipedia.org/wiki/CAIC_WZ-10', '{}'::jsonb, true),
  -- Boeing–Sikorsky RAH-66 Comanche (Q618637)
  ('boeing-sikorsky-rah-66-comanche', 'Boeing–Sikorsky RAH-66 Comanche', 'Boeing Rotorcraft Systems', 'militaire', 'Le RAH-66 Comanche était un hélicoptère destiné à la reconnaissance armée, à l''attaque légère et au combat air-air, qui devait rejoindre les rangs de l''United States Army Aviation Branch. Le projet a été abandonné en 2004.', NULL, '1996-01-04', NULL, 14.28, NULL, 3.37, NULL, NULL, NULL, NULL, 'États-Unis', NULL, 2, 5, 'https://upload.wikimedia.org/wikipedia/commons/8/87/Rah-66_c._2000.jpg', 'U.S. Army', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Rah-66_c._2000.jpg', 'Q618637', 'Boeing–Sikorsky RAH-66 Comanche', ARRAY['rah-66 comanche', 'boeing–sikorsky rah-66 comanche', 'comanche helicopter', 'boeing-sikorsky rah-66 comanche', 'rah66', 'commanche', 'boeing/sikorsky rah-66 comanche'], 'https://fr.wikipedia.org/wiki/Boeing-Sikorsky_RAH-66_Comanche', '{}'::jsonb, true),
  -- Mil Mi-14 (Q316212)
  ('mil-mi-14', 'Mil Mi-14', 'Mil / Kazan Helicopter', 'militaire', 'Le Mil Mi-14 (Code OTAN : Haze) est un hélicoptère amphibie soviétique conçu et réalisé par la société Mil. Ses missions sont la lutte anti-sous-marine et la recherche de mines.', NULL, '1969-09-01', NULL, 18.15, NULL, NULL, NULL, NULL, '1977-01-01', '2016-01-01', 'Union soviétique', 'Klimov TV3-117', 230, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Mi-14_P%C5%81_P%C5%82ock_2.JPG/1280px-Mi-14_P%C5%81_P%C5%82ock_2.JPG', 'Łukasz Golowanow', 'Attribution', NULL, 'https://commons.wikimedia.org/wiki/File:Mi-14_P%C5%81_P%C5%82ock_2.JPG', 'Q316212', 'Mil Mi-14', ARRAY['mil mi-14', 'haze', 'mil mi-14 haze', 'mi14', 'h-44', 'h44', 'mi-14'], 'https://fr.wikipedia.org/wiki/Mil_Mi-14', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Ka-25 (Q597404)
  ('kamov-ka-25', 'Ka-25', 'Kamov / Ulan-Ude Aviation Plant', 'militaire', 'Le Kamov Ka-25 (code OTAN Hormone) était un hélicoptère naval à rotors coaxiaux contrarotatifs du constructeur soviétique Kamov.', NULL, '1961-07-20', NULL, 9.75, NULL, NULL, NULL, NULL, '1971-12-02', NULL, NULL, 'turbomoteur', 460, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Ka-2583.jpg/1280px-Ka-2583.jpg', 'Department of Defense. American Forces Information Service. Defense Visual Information Center. 1994', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Ka-2583.jpg', 'Q597404', 'Kamov Ka-25', ARRAY['ka-25', 'kamov ka-25', 'hormone', 'ka25', 'h-43', 'h43', 'kamov ka-25 hormone'], 'https://fr.wikipedia.org/wiki/Kamov_Ka-25', '{"first_flight":["http://aviaros.narod.ru/ka-25.htm"],"length_m":["https://www.wikidata.org/wiki/Q29042798"],"units_built":["http://aviaros.narod.ru/ka-25.htm"],"service_entry":["http://aviaros.narod.ru/ka-25.htm"]}'::jsonb, true),
  -- Bell OH-58 Kiowa (Q694356)
  ('bell-oh-58-kiowa', 'Bell OH-58 Kiowa', 'Bell Textron', 'militaire', 'Le Bell OH-58 Kiowa est un hélicoptère militaire de reconnaissance fabriqué par Bell dérivé du Bell 206. Sa version OH-58D est la version militaire du Bell 407, elle-même dérivée du Bell 206L4. Il entra en service en mai 1969 sous la dénomination OH-58A et fut ensuite maintes fois amélioré. Construit jusqu''en 1989, il est un des hélicoptères les plus polyvalents de l''US Army de sa mise en service en 1969 à son remplacement, en 2017 par le Boeing AH-64 Apache.', NULL, '2013-04-26', NULL, 9.8, NULL, 2.92, 480, NULL, '1967-01-01', NULL, 'États-Unis', NULL, 2200, 2, 'https://upload.wikimedia.org/wikipedia/commons/6/6a/OH-58D_1.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:OH-58D_1.jpg', 'Q694356', 'Bell OH-58 Kiowa', ARRAY['bell oh-58 kiowa', 'h-58', 'kiowa', 'kiowa warrior', 'bell oh-58', 'oh58', 'h58', 'kiowa helicopter', 'oh-58', 'oh-58a/c/d kiowa/kiowa warrior'], 'https://fr.wikipedia.org/wiki/Bell_OH-58_Kiowa', '{}'::jsonb, true),
  -- Sikorsky S-92 (Q739040)
  ('sikorsky-s-92', 'Sikorsky S-92', 'Sikorsky Aircraft Corporation', 'autre', 'Le Sikorsky S-92 est un hélicoptère bimoteur doté d''un rotor principal à quatre pales construit par Sikorsky Aircraft à la fois pour le marché civil et militaire. Le S-92 a été développé à partir du Sikorsky S-70 et comporte des pièces communes avec celui-ci, telles que le rotor et le système de contrôle de vol. Depuis février 2009, le programme S-92 est incorporé dans Sikorsky Aircraft Corporation, la nouvelle entité de Sikorsky tournée vers le marché civil.', NULL, '1998-12-23', NULL, 17.1, NULL, NULL, 998, NULL, '2004-01-01', NULL, 'États-Unis', NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/b/b0/CHC_Helicopter_Scotia_Sikorsky_S-92A.jpg', 'Gary Watt', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:CHC_Helicopter_Scotia_Sikorsky_S-92A.jpg', 'Q739040', 'Sikorsky S-92', ARRAY['s-92', 'sikorsky s-92', 's92', 'sikorsky h-92 superhawk', 'h-92 superhawk', 'h92', 'superhawk'], 'https://fr.wikipedia.org/wiki/Sikorsky_S-92', '{}'::jsonb, true),
  -- Mi-10 (Q842257)
  ('mil-mi-10', 'Mi-10', 'Mil / Rostvertol', 'autre', 'Le Mil Mi-10 (Code OTAN : Harke-A) était un hélicoptère russe réalisé par le bureau d''études (OKB) Mil spécialement conçu pour le transport de charges externes. Il ne possédait pas de cabine passagers au sens commun du terme mais un habitacle très haut perché sur un train d’atterrissage formé de quatre jambes entre lesquelles pouvait prendre place un conteneur.', NULL, '1960-06-15', NULL, 32.86, NULL, NULL, NULL, NULL, NULL, NULL, 'Union soviétique', 'Soloviev D-25', 55, 4, 'https://upload.wikimedia.org/wikipedia/commons/8/82/Mil_Mi-10_%D0%9C%D0%BE%D1%81%D0%BA%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B9_%D0%B2%D0%B5%D1%80%D1%82%D0%BE%D0%BB%D0%B5%D1%82%D0%BD%D1%8B%D0%B9_%D0%B7%D0%B0%D0%B2%D0%BE%D0%B4_%D0%B8%D0%BC%D0%B5%D0%BD%D0%B8_%D0%9C%D0%B8%D0%BB%D1%8F.jpg', 'Unknown authorUnknown author', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Mil_Mi-10_%D0%9C%D0%BE%D1%81%D0%BA%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B9_%D0%B2%D0%B5%D1%80%D1%82%D0%BE%D0%BB%D0%B5%D1%82%D0%BD%D1%8B%D0%B9_%D0%B7%D0%B0%D0%B2%D0%BE%D0%B4_%D0%B8%D0%BC%D0%B5%D0%BD%D0%B8_%D0%9C%D0%B8%D0%BB%D1%8F.jpg', 'Q842257', 'Mil Mi-10', ARRAY['mi-10', 'mil mi-10', 'harke', 'v-10', 'mi10', 'mil mi-10 harke'], 'https://fr.wikipedia.org/wiki/Mil_Mi-10', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Mi-38 (Q1324759)
  ('mil-mi-38', 'Mi-38', 'Mil', 'autre', 'Le Mil Mi-38, appelé également Euromil Mi-38, est un hélicoptère russe réalisé par Kazan Helicopter et le bureau d''études MIL. La société Euromil a été spécialement créée dans le but de développer, produire et commercialiser cet appareil qui doit succéder aux modèles Mi-8 et Mi-17.', NULL, '2003-12-22', NULL, NULL, NULL, NULL, 1300, NULL, NULL, NULL, NULL, NULL, 4, 5, 'https://upload.wikimedia.org/wikipedia/commons/4/4d/Mi-38_on_MAKS-2005_airshow.jpg', 'Allocer', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Mi-38_on_MAKS-2005_airshow.jpg', 'Q1324759', 'Mil Mi-38', ARRAY['mi-38', 'mil mi-38', 'mi28', 'mil-38', 'euromil mi-38'], 'https://fr.wikipedia.org/wiki/Euromil_Mi-38', '{}'::jsonb, true),
  -- Eurocopter AS532 Cougar (Q167192)
  ('eurocopter-as532-cougar', 'Eurocopter AS532 Cougar', 'Inconnu', 'militaire', 'L''Aérospatiale AS532 Cougar est un hélicoptère de manœuvre et d''assaut biturbine fabriqué par Aérospatiale. Cet hélicoptère est une version améliorée du SA330 Puma. Sa cellule peut être en version courte ou allongée. Il peut être motorisé de trois manières : soit avec le Makila 1A, 1A1 ou 1A2. L''appellation civile de cet appareil est l''AS332 L, AS332L1 et AS332L2.', NULL, '1977-09-01', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'France', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Cougar_heli_ag1.jpg/1280px-Cougar_heli_ag1.jpg', 'Arnaud Gaillard (arnaud () amarys.com)', 'CC BY-SA 1.0', 'https://creativecommons.org/licenses/by-sa/1.0', 'https://commons.wikimedia.org/wiki/File:Cougar_heli_ag1.jpg', 'Q167192', 'Eurocopter AS532 Cougar', ARRAY['as532 cougar', 'eurocopter as532 cougar', 'eurocopter cougar', 'cougar', 'eurocopter as532', 'as.532', 'airbus helicopters h215m', 'h215m', 'as 532 cougar', 'airbus h215m', 'h 215m', 'eurocopter as-532 cougar', 'as-532 cougar'], 'https://fr.wikipedia.org/wiki/A%C3%A9rospatiale_AS532_Cougar', '{}'::jsonb, true),
  -- Sikorsky H-53 Sea Stallion (Q482538)
  ('sikorsky-ch-53-sea-stallion', 'Sikorsky H-53 Sea Stallion', 'Sikorsky Aircraft Corporation', 'militaire', 'Le Sikorsky CH-53 Stallion est un hélicoptère de manœuvre et d''assaut lourd militaire américain capable de transporter jusqu''à 55 personnes, bien que sa capacité habituelle soit de 37 hommes de troupe avec leur équipement. La version améliorée CH-53E Super Stallion, avec 3 moteurs, est capable d''emporter jusqu''à 15 tonnes de charge.', NULL, '1964-10-14', NULL, 26.97, NULL, 7.6, NULL, 5106, '1966-01-01', '2012-01-01', NULL, NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/CH-53D_Sea_Stallion.jpg/1280px-CH-53D_Sea_Stallion.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:CH-53D_Sea_Stallion.jpg', 'Q482538', 'Sikorsky CH-53 Sea Stallion', ARRAY['sikorsky h-53 sea stallion', 'sikorsky ch-53 sea stallion', 'h-53 sea stallion', 'sikorsky sea stallion', 'sikorsky ch-53', 'h-53', 'ch-53 stallion'], 'https://fr.wikipedia.org/wiki/Sikorsky_CH-53_Sea_Stallion', '{}'::jsonb, true),
  -- Eurocopter AS332 Super Puma (Q12257149)
  ('eurocopter-as332-super-puma', 'Eurocopter AS332 Super Puma', 'Aérospatiale / Airbus Helicopters', 'autre', 'L''Aérospatiale AS332 Super Puma, renommé Airbus Helicopters H215 en 2014 (pour les versions C1e et L1e ou correspondant à cette rénovation) est un hélicoptère de transport moyen franco-allemand destiné au marché civil et initialement conçu par la SNIAS. Directement dérivé du SA330 Puma dont il se présente comme une version agrandie et modernisée, il a donné naissance à une version encore en production en 2022, l''EC225 et à l’hélicoptère KAI Surion produit par Korea Aerospace Industries.', NULL, '1978-09-13', 278, 16.3, NULL, 4.6, 852, NULL, '1981-01-01', NULL, 'France', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/GFS_Super_Puma_on_USS_Mobile_Bay.jpg/1280px-GFS_Super_Puma_on_USS_Mobile_Bay.jpg', 'United States Navy, photographer not specified', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:GFS_Super_Puma_on_USS_Mobile_Bay.jpg', 'Q12257149', 'Eurocopter AS332 Super Puma', ARRAY['eurocopter as332 super puma', 'super puma', 'aérospatiale as 332', 'eurocopter as332', 'aerospatiale as 332', 'airbus helicopters as332', 'as 332', 'airbus helicopters h215', 'airbus h215', 'h215 super puma', 'h 215 superpuma', 'aerospatiale sa.332 super puma', 'aerospatiale as332 super puma', 'aérospatiale as332 super puma', 'h215', 'as332'], 'https://fr.wikipedia.org/wiki/A%C3%A9rospatiale_AS332_Super_Puma', '{}'::jsonb, true),
  -- AH-1Z Viper (Q2419137)
  ('bell-ah-1z-viper', 'AH-1Z Viper', 'Bell Textron', 'militaire', 'attack helicopter model by Bell', NULL, '2000-12-08', NULL, 17.8, NULL, NULL, 685, NULL, NULL, NULL, 'États-Unis', NULL, 28, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/AH-1Z_lift_off_the_USS_New_Orleans_%28LPD_18%29_%28cropped%29.jpg/1280px-AH-1Z_lift_off_the_USS_New_Orleans_%28LPD_18%29_%28cropped%29.jpg', 'U.S. Navy photo by Mass Communication Specialist 3rd Class Dominique Pineiro', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:AH-1Z_lift_off_the_USS_New_Orleans_(LPD_18)_(cropped).jpg', 'Q2419137', 'Bell AH-1Z Viper', ARRAY['bell ah-1z viper', 'ah-1z viper', 'bell ah-1z', 'viper', 'zulu cobra', 'bell 449', 'ah-1z'], 'https://en.wikipedia.org/wiki/Bell_AH-1Z_Viper', '{}'::jsonb, true),
  -- Robinson R22 (Q39652)
  ('robinson-r22', 'Robinson R22', 'Robinson Helicopter', 'autre', 'Le Robinson R22 est un hélicoptère civil léger, 2-places, conçu en 1973 et produit par le constructeur américain Robinson Helicopter depuis 1979.', NULL, '1975-01-01', NULL, 8.76, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/0/03/Flight.rob.arp.750pix.jpg', 'Adrian Pingstone', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Flight.rob.arp.750pix.jpg', 'Q39652', 'Robinson R22', ARRAY['r22', 'robinson r22', 'robinson r22 alpha'], 'https://fr.wikipedia.org/wiki/Robinson_R22', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true)
