  -- Sikorsky R-4 (Q564179)
  ('sikorsky-r-4', 'Sikorsky R-4', 'Sikorsky Aircraft Corporation', 'collection', 'Le Sikorsky R-4 est un hélicoptère construit par la société américaine Sikorsky Aircraft Corporation. Il fut le premier hélicoptère à être utilisé par l''USAF. L''hélicoptère était appelé Sikorsky HNS-1 par la United States Navy et la United States Coast Guard.', NULL, '1942-01-14', NULL, NULL, NULL, NULL, NULL, NULL, '1944-01-01', '1946-01-01', NULL, NULL, 131, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Igor_Sikorsky_in_a_U.S._Coast_Guard_HNS-1%2C_14_August_1944_%28232-8%29.jpg/1280px-Igor_Sikorsky_in_a_U.S._Coast_Guard_HNS-1%2C_14_August_1944_%28232-8%29.jpg', 'U.S. Coast Guard', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Igor_Sikorsky_in_a_U.S._Coast_Guard_HNS-1,_14_August_1944_(232-8).jpg', 'Q564179', 'Sikorsky R-4', ARRAY['sikorsky r-4', 'sikorsky model 47', 'sikorsky 47', 's-47', 'hoverfly', 'hns', 'sikorsky hns-1', 'hns-1', 'sikorsky s-47', 'sikorsky hns', 'sikorsky hoverfly'], 'https://fr.wikipedia.org/wiki/Sikorsky_R-4', '{}'::jsonb, true),
  -- AgustaWestland AW101 (Q398881)
  ('agustawestland-aw101', 'AgustaWestland AW101', 'Leonardo', 'militaire', 'L''EH101 est un hélicoptère de transport produit par le constructeur italien AgustaWestland (fusionné avec Leonardo-Finmeccanica en 2016). À la suite du rachat du constructeur britannique Westland par le groupe Finmeccanica, maison mère d''Agusta, la joint-venture EHI (European Helicopter Industries) a été renommée AgustaWestland International Limited et intégrée dans le groupe italien en janvier 2004. 101.', NULL, '1987-10-09', NULL, 22.81, NULL, 6.62, 833, 4575, '2000-01-01', NULL, 'Italie', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/AgustaWestland_HH-101A_Caesar_%28cropped%29.jpg/1280px-AgustaWestland_HH-101A_Caesar_%28cropped%29.jpg', 'Gian Marco Anzellotti', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:AgustaWestland_HH-101A_Caesar_(cropped).jpg', 'Q398881', 'AgustaWestland AW101', ARRAY['agustawestland aw101', 'eh101', 'eh industries limited', 'ehi 01', 'eh-101 merlin', 'agusta-westland eh-101', 'agustawestland eh-101', 'merlin helicopter', 'leonardo aw101', 'ehi aw101', 'ehi eh 101', 'h-101', 'merlin', 'aw 101', 'eh industries eh101', 'wg.34', 'aw101', 'agustawestland eh-101 merlin', 'ch-149 chimo', 'ch-149 cormorant', 'pp9', 'ch-148 petrel', 'pp0', 'pp6', 'agusta westland eh101', 'westland merlin', 'pp5', 'eh-101', 'pp8'], 'https://fr.wikipedia.org/wiki/AgustaWestland_EH101_Merlin', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- HAL Dhruv (Q762486)
  ('hal-dhruv', 'HAL Dhruv', 'Hindustan Aeronautics', 'autre', 'Le HAL Dhruv est un hélicoptère moyen polyvalent conçu par la société indienne HAL en collaboration avec Messerschmitt-Bölkow-Blohm pour succéder aux Alouette III de l''armée indienne. Il a commencé à entrer en service dans l''armée indienne en 2002 et s''est exporté vers l''Équateur, l''Ile Maurice, le Népal, et les Maldives. Le Dhruv est disponible dans différentes versions, dont certaines civiles.', NULL, '1992-08-20', NULL, 15.87, NULL, 4.98, 650, NULL, '2002-03-01', NULL, 'Inde', 'HAL/Turbomeca Shakti / Turbomeca TM 333', 335, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Indian_air_force_dhruv_helicopter_j4042_arp.jpg/1280px-Indian_air_force_dhruv_helicopter_j4042_arp.jpg', 'Arpingstone', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Indian_air_force_dhruv_helicopter_j4042_arp.jpg', 'Q762486', 'HAL Dhruv', ARRAY['dhruv', 'hal dhruv', 'alh', 'advanced light helicopter', 'hal alh'], 'https://fr.wikipedia.org/wiki/HAL_Dhruv', '{}'::jsonb, true),
  -- Sikorsky S-76 (Q1141716)
  ('sikorsky-s-76', 'Sikorsky S-76', 'Sikorsky Aircraft Corporation', 'autre', 'Le Sikorsky S-76 Spirit est un hélicoptère à usage commercial, produit par le constructeur américain Sikorsky Aircraft Corporation. C''est un appareil polyvalent de taille moyenne. Il est équipé d''un rotor de sustentation et d''un rotor anticouple, chacun doté de quatre pales, et d''un train d''atterrissage rétractable.', NULL, '1977-03-13', NULL, 13.44, NULL, NULL, NULL, NULL, '1979-01-01', NULL, NULL, NULL, 537, 3, 'https://upload.wikimedia.org/wikipedia/commons/4/44/HeliJet_S76_landing_at_Vancouver_Harbour.jpg', 'Original uploader was MarekW at en.wikipedia. Later version(s) were uploaded by BilCat, Frionn at en.wikipedia.', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:HeliJet_S76_landing_at_Vancouver_Harbour.jpg', 'Q1141716', 'Sikorsky S-76', ARRAY['s-76', 'sikorsky s-76', 's76', 'sikorsky s-76 spirit'], 'https://fr.wikipedia.org/wiki/Sikorsky_S-76', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
