  ('hal-prachand', 'HAL Light Combat Helicopter', 'Hindustan Aeronautics', 'militaire', 'Le HAL Light Combat Helicopter (LCH) Prachand est un hélicoptère d''attaque polyvalent actuellement développé par la société indienne HAL à destination des forces de l''armée de l''air et de l''armée de terre indiennes.', NULL, '2010-03-29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Inde', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/HAL_LCH_at_Aero_india_2013.JPG/1280px-HAL_LCH_at_Aero_india_2013.JPG', 'Pritishp333', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:HAL_LCH_at_Aero_india_2013.JPG', 'Q1512304', 'HAL Prachand', ARRAY['hal light combat helicopter', 'hal prachand', 'lch', 'light combat helicopter (hal)', 'hal lch'], 'https://fr.wikipedia.org/wiki/HAL_Prachand', '{}'::jsonb, true),
  -- AS565 Panther (Q39613)
  ('eurocopter-as565-panther', 'AS565 Panther', 'Airbus Helicopters', 'militaire', 'L''Aérospatiale AS565 Panther est un hélicoptère français moyen polyvalent, c''est la version militaire du SA365 Dauphin. Le Panther peut être utilisé dans un large éventail de rôles militaires : appui feu, lutte anti-sous-marine, lutte anti-navire, recherche et sauvetage (SAR), transport de troupes, évacuation sanitaire (Evasan) et de renseignement d''intérêt maritime (ISR) depuis le standard 2. En janvier 2014, il est renommé AS565 MBe.', NULL, '1984-02-29', NULL, 13.68, NULL, 3.97, 827, 5865, NULL, NULL, NULL, NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Marina-Panther-Unitasgold2009.jpg/1280px-Marina-Panther-Unitasgold2009.jpg', 'Mass Communication Specialist Seaman Patrick Grieco', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Marina-Panther-Unitasgold2009.jpg', 'Q39613', 'Eurocopter AS565 Panther', ARRAY['as565 panther', 'eurocopter as565 panther', 'eurocopter as565', 'airbus as565', 'panther', 'eurocopter panther', 'aérospatiale as565 panther', 'aérospatiale panther', 'hélicoptère panther'], 'https://fr.wikipedia.org/wiki/A%C3%A9rospatiale_AS565_Panther', '{}'::jsonb, true),
  -- Fa 223 Drachen (Q609052)
  ('focke-achgelis-fa-223-drache', 'Fa 223 Drachen', 'Focke-Achgelis', 'collection', 'Le Focke-Achgelis Fa 223 Drachen (Dragon) était un hélicoptère militaire développé par la société Focke-Achgelis pendant la Seconde Guerre mondiale. Il est une évolution du Focke-Wulf Fw 61 Hornisse (« frelon ») d''avant-guerre. C''est sur cet appareil que fut mis au point le dispositif de plateau cyclique généralement utilisé encore aujourd''hui et qui permet au pilote de commander chacune des pales individuellement.', NULL, '1940-08-03', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 18, 5, 'https://upload.wikimedia.org/wikipedia/commons/a/af/Fa_223_im_Hubschraubermuseum_B%C3%BCckeburg.jpg', 'Matthias Stäblein', 'CC BY-SA 3.0 de', 'https://creativecommons.org/licenses/by-sa/3.0/de/deed.en', 'https://commons.wikimedia.org/wiki/File:Fa_223_im_Hubschraubermuseum_B%C3%BCckeburg.jpg', 'Q609052', 'Focke-Achgelis Fa 223 Drache', ARRAY['fa 223 drache', 'fa 223 drachen', 'focke-achgelis fa 223 drache', 'focke-achgelis fa 223'], 'https://fr.wikipedia.org/wiki/Focke-Achgelis_Fa_223_Drachen', '{}'::jsonb, true),
  -- Sikorsky S-55 (Q694765)
  ('sikorsky-h-19-chickasaw', 'Sikorsky S-55', 'Sikorsky Aircraft Corporation', 'collection', 'Le Sikorsky H-19 (aussi connu sous les noms de S-55 ou Chickasaw) est un hélicoptère de manœuvre et d''assaut construit par la société américaine Sikorsky Aircraft Corporation. Il a été utilisé par l''armée des États-Unis (United States Army) et l''United States Air Force. Il a également été construit sous licence par Westland Helicopters sous le nom de Westland Whirlwind au Royaume-Uni.', NULL, '1949-11-10', NULL, 12.91, NULL, 4.07, 725, 3200, '1950-04-16', '1969-02-26', NULL, NULL, 1102, 3, 'https://upload.wikimedia.org/wikipedia/commons/a/a2/Sikorsky_S-55_inflight_c.jpg', 'U.S. Army', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Sikorsky_S-55_inflight_c.jpg', 'Q694765', 'Sikorsky H-19 Chickasaw', ARRAY['s-55', 'sikorsky s-55', 'sikorsky h-19 chickasaw', 'h-19', 'hrs', 'sikorsky 55', 'uh-19', 'ho4s', 's55', 'h-19 chickasaw', 'sikorsky h-19'], 'https://fr.wikipedia.org/wiki/Sikorsky_H-19', '{}'::jsonb, true),
