  -- CH-53E Super Stallion (Q856317)
  ('sikorsky-ch-53e-super-stallion', 'CH-53E Super Stallion', 'Sikorsky Aircraft Corporation', 'militaire', 'Le Sikorsky CH-53E Super Stallion (en anglais, Super étalon) est un hélicoptère de transport lourd développé par Sikorsky Aircraft pour le Corps des Marines des États-Unis sur la base du CH-53 Sea Stallion. Les modifications principales apportées sont l''addition d''un troisième moteur, d''une septième pale au rotor principal et la possibilité de basculer le rotor de queue de 20 degrés.', NULL, NULL, NULL, 22.38, NULL, NULL, NULL, NULL, NULL, NULL, 'États-Unis', 'T64', 234, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/US_Navy_080710-N-5148B-031_A_CH-53E_Super_Stallion_helicopter_assigned_to_Marine_Medium_Helicopter_Squadron_%28HMM%29_165_prepares_to_land_on_the_flight_deck_of_the_amphibious_assault_ship_USS_Peleliu_%28LHA_5%29.jpg/1280px-thumbnail.jpg', 'U.S. Navy photo by Mass Communication Specialist Seaman Sarah E. Bitter', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:US_Navy_080710-N-5148B-031_A_CH-53E_Super_Stallion_helicopter_assigned_to_Marine_Medium_Helicopter_Squadron_(HMM)_165_prepares_to_land_on_the_flight_deck_of_the_amphibious_assault_ship_USS_Peleliu_(LHA_5).jpg', 'Q856317', 'Sikorsky CH-53E Super Stallion', ARRAY['sikorsky ch-53e super stallion', 'ch-53e super stallion', 'sikorsky s-80', 's80', 's-80 helicopter', 'super stallion', 'sikorsky super stallion', 'helicopter design 53 series e/f', 'sikorsky h-53e/f super stallion', 'h-53 super stallion', 'h-53e/f super stallion', 'sikorsky 80 super stallion', 'ch-53e'], 'https://fr.wikipedia.org/wiki/Sikorsky_CH-53E_Super_Stallion', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
