  -- Hughes OH-6 Cayuse (Q1050858)
  ('hughes-oh-6-cayuse', 'Hughes OH-6 Cayuse', 'Hughes Helicopters', 'militaire', 'L''OH-6 Cayuse est un hélicoptère américain développé par la division hélicoptère de l''entreprise Hughes Aircraft; surnommé "Loach" du fait de sa prononciation de l''acronyme anglais LOH (light Observation Helicopter), il est capable d''accomplir diverses tâches telles que des missions de transport de personnel, évacuation de blessés, escorte, attaque et observation. Hughes a également développé une version civile du OH-6 appelée Hughes MD 500.', NULL, '1963-02-27', NULL, NULL, NULL, NULL, 430, NULL, NULL, NULL, 'États-Unis', NULL, 1434, 3, 'https://upload.wikimedia.org/wikipedia/commons/1/12/Hughes_YOH-6A_Cayuse_US_Army_in_flight.jpg', 'U.S. Army', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Hughes_YOH-6A_Cayuse_US_Army_in_flight.jpg', 'Q1050858', 'Hughes OH-6 Cayuse', ARRAY['hughes oh-6 cayuse', 'cayuse helicopter', 'eh-6', 'loach', 'h-6 cayuse', 'hughes cayuse', 'th-6', 'observation helicopter design 6', 'oh-6', 'hughes modèle 369', 'cayuse'], 'https://fr.wikipedia.org/wiki/Hughes_OH-6_Cayuse', '{}'::jsonb, true),
