  ('md-helicopters-mh-6-little-bird', 'MH-6 Little Bird', 'MD Helicopters', 'militaire', 'Le MH-6 Little Bird et sa variante armée le AH-6 sont des hélicoptères légers utilisés par les forces d''opérations spéciales américaines, dérivés du Hughes OH-6 Cayuse puis du Hughes MD 500 et produits par MD Helicopters.', NULL, '1963-02-27', NULL, 9.8, NULL, NULL, 430, NULL, NULL, NULL, 'États-Unis', NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/6/62/Mh-6_002x.jpg', 'US Army', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Mh-6_002x.jpg', 'Q3272950', 'MD Helicopters MH-6 Little Bird', ARRAY['mh-6 little bird', 'md helicopters mh-6 little bird', 'mcdonnell douglas mh-6', 'ah-6/mh-6 little bird'], 'https://fr.wikipedia.org/wiki/MD_Helicopters_MH-6_Little_Bird', '{}'::jsonb, true),
  -- Bell UH-1Y Venom (Q2529305)
  ('bell-uh-1y-venom', 'Bell UH-1Y Venom', 'Bell', 'militaire', 'Le Bell UH-1Y Venom (« venin » en français) est un hélicoptère de manœuvre et d''assaut américain construit par Bell Aircraft Corporation. Il est destiné à remplacer le Bell UH-1 Iroquois dans le corps des Marines.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'États-Unis', NULL, 160, 4, 'https://upload.wikimedia.org/wikipedia/commons/9/9c/U.S._Marine_Corps_UH-1Y_flies_over_a_live-fire_range_in_search_of_simulated_enemy_targets_during_a_Tactical_Air_Control_Party.JPG', 'Lance Cpl. Clarence Leake', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:U.S._Marine_Corps_UH-1Y_flies_over_a_live-fire_range_in_search_of_simulated_enemy_targets_during_a_Tactical_Air_Control_Party.JPG', 'Q2529305', 'Bell UH-1Y Venom', ARRAY['bell uh-1y venom', 'venom', 'uh1y venom', 'uh-1y super huey', 'super huey', 'uh-1 venom', 'uh-1 yankee', 'uh-1y venom'], 'https://fr.wikipedia.org/wiki/Bell_UH-1Y_Venom', '{}'::jsonb, true),
  -- Eurocopter EC225 (Q219152)
  ('eurocopter-ec225-super-puma', 'Eurocopter EC225', 'Airbus Helicopters', 'autre', 'L''Airbus Helicopters H225 Super Puma est un hélicoptère de la classe 11 tonnes fabriqué par Airbus Helicopters, anciennement Eurocopter qui a effectué son premier vol en novembre 2000. Son équivalent militaire est le Caracal. Il est le dernier né de la famille des Super Puma. Depuis le changement de dénomination sociale de l''hélicoptériste en janvier 2014, les EC225 Super Puma sont désignés H225 Super Puma.', NULL, '2000-11-27', NULL, 19.5, NULL, 4.97, NULL, NULL, '2004-12-01', NULL, 'France', NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Bristow_Helicopters_-_Eurocopter_EC-225LP.jpg', 'Gary Watt', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:Bristow_Helicopters_-_Eurocopter_EC-225LP.jpg', 'Q219152', 'Eurocopter EC225 Super Puma', ARRAY['h225 super puma', 'eurocopter ec225', 'eurocopter ec225 super puma', 'airbus helicopters ec225', 'eurocopter ec 225', 'super puma 2', 'super puma mk.2', 'ec225 super puma', 'ec 225 super puma', 'ec 225', 'ec225'], 'https://fr.wikipedia.org/wiki/Airbus_Helicopters_H225_Super_Puma', '{}'::jsonb, true),
  -- Boeing-Vertol CH-46 Sea Knight (Q282934)
  ('boeing-vertol-ch-46-sea-knight', 'Boeing-Vertol CH-46 Sea Knight', 'Boeing Rotorcraft Systems', 'militaire', 'Le Boeing CH-46 Sea Knight est un hélicoptère moyen de transport à rotor en tandem. Il est utilisé par les Marines américains pour le transport de troupes, de matériels et de ravitaillement par tous les temps, de jour comme de nuit. Il est aussi capable de remplir d''autres missions comme le soutien sur le champ de bataille, le sauvetage (SAR), le sauvetage armé (CSAR), l''évacuation sanitaire et le soutien des postes de ravitaillement avancés.', NULL, '1958-04-22', NULL, 13.66, NULL, NULL, NULL, NULL, '1964-01-01', NULL, 'États-Unis', 'T58', NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Sea_Knight.jpg/1280px-Sea_Knight.jpg', 'Staff Sgt. Raymie G. Cruz', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Sea_Knight.jpg', 'Q282934', 'Boeing Vertol CH-46 Sea Knight', ARRAY['boeing vertol ch-46 sea knight', 'boeing-vertol ch-46 sea knight', 'sea knight', 'model 107', 'ch-113 labrador', 'boeing-vertol 107', 'boeing-vertol h-46 sea knight', 'uh-46', 'hh-46', 'hrb-1', 'boeing vertol hrb-1', 'ch-46 sea knight', 'boeing vertol h-46 sea knight', 'hrb', 'h-46'], 'https://fr.wikipedia.org/wiki/Boeing_CH-46_Sea_Knight', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Bell 407 (Q815682)
  ('bell-407', 'Bell 407', 'Bell Textron', 'autre', 'Le Bell 407 est un hélicoptère civil monomoteur dérivé du Bell 206 L-4 LongRanger en service depuis 1995. Il est fabriqué par la société Bell Aircraft Corporation. Dans la configuration normale, 7 personnes peuvent voler dans l''appareil. Il utilise les pales d''une version militaire, le Bell OH-58D Kiowa Warrior. Le Bell 407 fournit également la base du drone Northrop Grumman MQ-8C Fire Scout. Il est toujours commercialisé en 2023.', NULL, '1995-06-29', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'États-Unis / Canada', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Bell_407_-N23986.jpg/1280px-Bell_407_-N23986.jpg', 'stuart.mike', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:Bell_407_-N23986.jpg', 'Q815682', 'Bell 407', ARRAY['bell 407', 'b407', 'bell 417', 'bell model 407', 'model 407', '407'], 'https://fr.wikipedia.org/wiki/Bell_407', '{}'::jsonb, true),
  -- Flettner Fl 282 Kolibri (Q519370)
  ('flettner-fl-282', 'Flettner Fl 282 Kolibri', 'Flettner', 'collection', 'Le Flettner Fl 282 Kolibri était un hélicoptère militaire de reconnaissance et d’observation réalisé par Anton Flettner en Allemagne pendant la Seconde Guerre mondiale. Sa caractéristique principale était son système de propulsion et de sustentation constitué de deux rotors bipales engrenants dont les mâts placés en « V » étaient entraînés par une boîte de transmission commune.', NULL, '1941-10-30', NULL, NULL, NULL, NULL, NULL, NULL, '1942-10-14', '1945-01-01', NULL, NULL, 24, 5, 'https://upload.wikimedia.org/wikipedia/commons/d/d8/Flettner_282_airborne.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Flettner_282_airborne.jpg', 'Q519370', 'Flettner Fl 282', ARRAY['flettner fl 282', 'flettner fl 282 kolibri', 'fletcher fl 282 kolibri', 'hummingbird'], 'https://fr.wikipedia.org/wiki/Flettner_Fl_282_Kolibri', '{}'::jsonb, true),
  -- Eurocopter EC120 (Q39665)
  ('eurocopter-ec120-colibri', 'Eurocopter EC120', 'Airbus Helicopters / Harbin Aircraft Manufacturing Corporation', 'autre', 'L''Eurocopter EC120 Colibri est un hélicoptère léger monoturbine conçu par Eurocopter en partenariat avec China National Aero-Technology Import & Export Corporation (en), Harbin Aircraft Manufacturing Corporation et ST Aerospace, et assemblé dans les ateliers d''Eurocopter à Marignane. Il a été conçu pour transporter un pilote et quatre passagers, et doté d''une polyvalence pour s''adapter aux besoins de ses clients, qu''ils soient des acquéreurs privés ou des organismes publics, voire militaires.', NULL, '1995-06-09', 222, NULL, NULL, NULL, 709, NULL, NULL, NULL, 'France / République populaire de Chine', NULL, 700, 3, 'https://upload.wikimedia.org/wikipedia/commons/b/b7/Eurocopter_Colibri_750pix.jpg', 'Adrian Pingstone', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Eurocopter_Colibri_750pix.jpg', 'Q39665', 'Eurocopter EC120 Colibri', ARRAY['h120 colibri', 'eurocopter ec120', 'eurocopter ec120 colibri', 'colibri', 'hc-120', 'eurocopter colibri', 'airbus helicopters ec120', 'eurocopter ec-120'], 'https://fr.wikipedia.org/wiki/Eurocopter_EC120_Colibri', '{"range_km":["http://www.helicopters.airbus.com/website/docs_wsw/RUB_430/tile_4624/H120-2016.pdf"]}'::jsonb, true),
  -- Bell 429 (Q815686)
  ('bell-429-globalranger', 'Bell 429', 'Bell Textron', 'autre', 'Le Bell 429 est un hélicoptère bimoteur léger construit par l''hélicoptèriste américain Bell Helicopter.', NULL, '2007-02-27', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/b/b4/Bell429_RA-01601_%289772552923%29.jpg', 'Aleksandr Markin', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Bell429_RA-01601_(9772552923).jpg', 'Q815686', 'Bell 429 GlobalRanger', ARRAY['bell 429 globalranger', 'bell 429', 'globalranger', 'global ranger', 'bell model 429', 'model 429 globalranger'], 'https://fr.wikipedia.org/wiki/Bell_429', '{}'::jsonb, true),
  -- Mil Mi-34 (Q1704320)
  ('mil-mi-34', 'Mil Mi-34', 'Mil', 'autre', 'Le Mil Mi-34 (code OTAN Hermit) est un hélicoptère léger conçu par l''usine d''hélicoptères Mil de Moscou. Il est disponible en configuration deux ou quatre places pour un usage civil et la formation. Il a effectué son premier vol en 1986 et introduit au Salon de l''aéronautique de Paris en 1987. Le Mi-34 de production est entré en service en 1993, et est capable d''effectuer des acrobaties aériennes telles que des rouleaux et des boucles.', NULL, '1986-11-17', NULL, NULL, NULL, NULL, NULL, NULL, '1989-01-01', NULL, 'Union soviétique', 'Vedeneïev M-14', 27, 5, 'https://upload.wikimedia.org/wikipedia/commons/1/14/Mi-34.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Mi-34.jpg', 'Q1704320', 'Mil Mi-34', ARRAY['mil mi-34', 'mi-34', 'hermit'], 'https://fr.wikipedia.org/wiki/Mil_Mi-34', '{}'::jsonb, true),
