  -- Yakovlev Yak-24 (Q166826)
  ('yakovlev-yak-24', 'Yakovlev Yak-24', 'Yakovlev', 'autre', 'Le Yakovlev Yak-24 (Code OTAN Horse) est un hélicoptère bimoteur de transport à rotor en tandem développé en URSS.', NULL, '1952-07-03', NULL, NULL, NULL, NULL, NULL, NULL, '1955-01-01', NULL, NULL, 'ASh-82', 40, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Jakowlew_Jak-24_Horse.JPG/1280px-Jakowlew_Jak-24_Horse.JPG', 'Bernhard Gröhl', 'CC BY 2.5', 'https://creativecommons.org/licenses/by/2.5', 'https://commons.wikimedia.org/wiki/File:Jakowlew_Jak-24_Horse.JPG', 'Q166826', 'Yakovlev Yak-24', ARRAY['yakovlev yak-24', 'horse', 'yak-24'], 'https://fr.wikipedia.org/wiki/Yakovlev_Yak-24', '{}'::jsonb, true),
  -- Sikorsky S-58 (Q507814)
  ('sikorsky-h-34', 'Sikorsky S-58', 'Sikorsky Aircraft Corporation / Sud-Aviation', 'autre', 'Le Sikorsky S-58 est un hélicoptère militaire américain, conçu à l''origine par la Sikorsky Aircraft Corporation pour l''United States Navy pour le service de la lutte anti-sous-marine. Entré en service sous l''appellation HSS-1 Seabat, puis HUS-1 Seahorse en version utilitaire, il a ensuite été retenu par l''United States Army, au sein de laquelle il est devenu H-34 Choctaw.', NULL, '1954-03-08', NULL, 16.69, NULL, NULL, NULL, NULL, '1955-08-01', NULL, 'États-Unis', NULL, 2108, 2, 'https://upload.wikimedia.org/wikipedia/commons/2/24/Sikorsky_S-58_landing_c.jpg', 'U.S. Army', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Sikorsky_S-58_landing_c.jpg', 'Q507814', 'Sikorsky H-34', ARRAY['sikorsky s-58', 'sikorsky h-34', 'uh-34', 'sikorsky hus', 'choctaw', 'sh-34', 'hus', 'sikorsky choctaw', 'vh-34', 'h-34', 'hss-1', 'ch-34', 's58', 'sikorsky h-19 chickasaw'], 'https://fr.wikipedia.org/wiki/Sikorsky_H-34', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Vertol H-21 (Q700828)
  ('piasecki-h-21', 'Vertol H-21', 'Piasecki Helicopter / Weser Flugzeugbau', 'collection', 'Le Vertol H-21 (selon la nomenclature de l''US Air Force) ou le Piasecki Helicopter PD 22, est le premier hélicoptère lourd de transport utilisé en grand nombre dans des opérations militaires. Développé à partir de 1945 par Frank Piasecki et opérationnel dans les armées de plusieurs pays de la deuxième moitié des années 1950 jusqu''à la fin des années 1960, il possède deux rotors en tandem.', NULL, '1952-04-11', NULL, 26.2, NULL, NULL, NULL, NULL, '1954-01-01', '1967-01-01', 'États-Unis', NULL, 707, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Vertol_CH-21B_Workhorse_USAF.jpg/1280px-Vertol_CH-21B_Workhorse_USAF.jpg', 'U.S. Air Force photo', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Vertol_CH-21B_Workhorse_USAF.jpg', 'Q700828', 'Piasecki H-21', ARRAY['h-21 shawnee', 'vertol h-21', 'piasecki h-21', 'h21', 'work horse', 'workhorse', 'shawnee', 'h-21 work horse', 'piasecki 42', 'piasecki model 42', 'model 42', 'ch-21', 'piasecki ch-21', 'hh-21', 'sh-21', 'piasecki model 44', 'piasecki 44', 'banane volante', 'ch-21 shawnee', 'sikorsky h-21'], 'https://fr.wikipedia.org/wiki/Vertol_H-21', '{}'::jsonb, true),
  -- SA 321 Super Frelon (Q794582)
  ('aerospatiale-sa-321-super-frelon', 'SA 321 Super Frelon', 'Aérospatiale', 'militaire', '321 Super Frelon est un hélicoptère lourd conçu par la société française Sud-Aviation, en collaboration avec Sikorsky (rotors) et Fiat (transmission). La flottille 32F l''a utilisé pendant 44 ans de 1966 à 2010. Le dernier Super Frelon français a atterri le 6 mai 2010 au musée de l''aviation navale à Rochefort. Il est remplacé par l''EC225 d''Eurocopter et par le NH90.', NULL, '1962-12-07', NULL, 19.4, NULL, 4.93, 650, 3150, '1966-01-01', NULL, NULL, 'Turbomeca Turmo', 110, 4, 'https://upload.wikimedia.org/wikipedia/commons/8/89/Super_Frelon_4.jpg', 'Guillaume Rueda', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Super_Frelon_4.jpg', 'Q794582', 'Aérospatiale SA 321 Super Frelon', ARRAY['sa 321 super frelon', 'aérospatiale sa 321 super frelon', 'aérospatiale sa 321', 'super frelon', 'aerospatiale super frelon', 'aérospatiale super frelon', 'sa321', 'aerospatiale sa.321 super frelon', 'aerospatiale sa 321 super frelon', 'sud aviation', 'super-frelon', 'sa.321', 'sa.3210', 'sa3210', 'sa.3220', 'sa3220', 'sa.3230', 'sa3230'], 'https://fr.wikipedia.org/wiki/Sud-Aviation_SA321_Super_Frelon', '{}'::jsonb, true),
  -- Sikorsky S-48 (Q1810661)
  ('sikorsky-h-5', 'Sikorsky S-48', 'Sikorsky Aircraft Corporation / AgustaWestland', 'collection', 'Le Sikorsky H-5 est un hélicoptère construit par la société américaine Sikorsky Aircraft Corporation. Il est aussi connu sous les noms de R-5, S-51, HO3S-1, ou Horse (R-5 jusqu''en 1948; désignation du constructeur VS-327).', NULL, '1943-08-18', NULL, NULL, NULL, NULL, NULL, NULL, '1945-01-01', '1957-01-01', NULL, NULL, 379, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Sikorsky_YH-5A_USAF.jpg/1280px-Sikorsky_YH-5A_USAF.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Sikorsky_YH-5A_USAF.jpg', 'Q1810661', 'Sikorsky H-5', ARRAY['sikorsky s-51 dragonfly', 'sikorsky s-48', 'sikorsky h-5', 's-48 (sikorsky)', 's48 (sikorsky)', 'r-5 dragonfly', 'r-5 (sikorsky)', 'r5 dragonfly', 'r5 (sikorsky)', 'dragonfly (sikorsky r-5)', 'dragonfly (r-5)', 'dragonfly (h-5)', 'h-5 dragonfly', 'h5 dragonfly', 'sikorsky 48', 'vs-327', 'sikorsky s-51'], 'https://fr.wikipedia.org/wiki/Sikorsky_H-5', '{}'::jsonb, true),
