  -- AgustaWestland AW159 (Q398898)
  ('agustawestland-aw159-wildcat', 'AgustaWestland AW159', 'Leonardo / AgustaWestland', 'militaire', 'L''AgustaWestland AW159 Wildcat (auparavant dénommé Future Lynx ou Lynx Wildcat) est un hélicoptère militaire européen construit par la société Agusta Westland (fusionné avec Leonardo en 2016). C''est une version améliorée du Westland Lynx.', NULL, '2009-11-12', NULL, 15.24, NULL, 3.73, NULL, NULL, '2014-08-29', NULL, 'Royaume-Uni', NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/c/c9/AgustaWestland_AW-159_Lynx_Wildcat_AH1_-_Chris_Lofting.jpg', 'Chris Lofting', 'GFDL 1.2', 'http://www.gnu.org/licenses/old-licenses/fdl-1.2.html', 'https://commons.wikimedia.org/wiki/File:AgustaWestland_AW-159_Lynx_Wildcat_AH1_-_Chris_Lofting.jpg', 'Q398898', 'AgustaWestland AW159 Wildcat', ARRAY['aw159 wildcat', 'agustawestland aw159', 'agustawestland aw159 wildcat', 'agustawestland aw159 lynx wildcat', 'wildcat aw159', 'agustawestland wildcat', 'leonardo aw159 wildcat', 'leonardo wildcat', 'aw 159 wildcat', 'future lynx', 'lynx wildcat', 'wildcat'], 'https://fr.wikipedia.org/wiki/AgustaWestland_AW159_Wildcat', '{}'::jsonb, true),
  -- MD 500 (Q848899)
  ('md-helicopters-md-500', 'MD 500', 'MD Helicopters', 'militaire', 'Le Hughes MD 500 est un hélicoptère civil américain développé par Hughes Helicopters sur la base de l''OH-6 Cayuse, mais c''est également le nom usuel de la gamme d''hélicoptères légers du même constructeur, incluant les MD 500E, MD 520N, et MD 530F.', NULL, '1963-01-01', NULL, 7.01, NULL, NULL, NULL, NULL, NULL, NULL, 'États-Unis', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Md_helicopters_md-500e_g-sscl_arp.jpg/1280px-Md_helicopters_md-500e_g-sscl_arp.jpg', 'Adrian Pingstone (Arpingstone)', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Md_helicopters_md-500e_g-sscl_arp.jpg', 'Q848899', 'MD Helicopters MD 500', ARRAY['md helicopters md 500', 'md 500', 'hughes 369', 'nh-500', 'mcdonnell douglas md 500', 'hughes 500', 'mcdonnell douglas model 500', 'boeing md 520n', 'hughes md 500', 'hughes md500', 'md500'], 'https://fr.wikipedia.org/wiki/Hughes_MD_500', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Kamov Ka-226 (Q1723251)
  ('kamov-ka-226', 'Kamov Ka-226', 'Kamov', 'autre', 'Le Kamov Ka-226 est un hélicoptère léger polyvalent russe bimoteur. Le Ka-226 dispose d''une nacelle de mission interchangeable plutôt qu''une cabine conventionnelle, permettant l''utilisation de diverses configurations de transport ou d''équipement. Le Ka-226 est entré en service en 2002. Les variantes du Ka-226 portent l''appellation OTAN Hoodlum.', NULL, '1997-09-04', NULL, 8.1, NULL, 4.15, NULL, 6500, '2002-01-01', NULL, NULL, NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Kamov_Ka-226_MAKS_2005.jpg/1280px-Kamov_Ka-226_MAKS_2005.jpg', 'No machine-readable author provided. .:Ajvol:. assumed (based on copyright claims).', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Kamov_Ka-226_MAKS_2005.jpg', 'Q1723251', 'Kamov Ka-226', ARRAY['kamov ka-226', 'kamov ka-226t'], 'https://fr.wikipedia.org/wiki/Kamov_Ka-226', '{}'::jsonb, true),
  -- Sikorsky CH-53K King Stallion (Q1084867)
  ('sikorsky-ch-53k-king-stallion', 'Sikorsky CH-53K King Stallion', 'Sikorsky Aircraft Corporation', 'militaire', 'Le Sikorsky CH-53K King Stallion est un hélicoptère de transport lourd développé par Sikorsky Aircraft pour le Corps des Marines des États-Unis afin de remplacer leurs CH-53E Super Stallion. Il s''agit de l''hélicoptère le plus grand et le plus lourd de l''armée américaine. Deux cents appareils devaient être commandés et livrés entre 2018 et, selon les prévisions de 2022, 2030 pour un coût total de plus de 23 milliards de dollars.', NULL, '2015-10-27', NULL, 30.2, NULL, NULL, 852, NULL, '2022-04-22', NULL, 'États-Unis', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Sikorsky_CH-53K_King_Stallion%2C_ILA_2018%2C_Sch%C3%B6nefeld_%281X7A6778%29.jpg/1280px-Sikorsky_CH-53K_King_Stallion%2C_ILA_2018%2C_Sch%C3%B6nefeld_%281X7A6778%29.jpg', 'Matti Blume', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Sikorsky_CH-53K_King_Stallion,_ILA_2018,_Sch%C3%B6nefeld_(1X7A6778).jpg', 'Q1084867', 'Sikorsky CH-53K King Stallion', ARRAY['ch-53k king stallion', 'sikorsky ch-53k king stallion', 'sikorsky ch-53 king stallion', 'king stallion', 'ch-53 king stallion', 'helicopter design 53 transport series k', 'sikorsky king stallion', 'h-53 king stallion', 'sikrosky h-53 king stallion'], 'https://fr.wikipedia.org/wiki/Sikorsky_CH-53K_King_Stallion', '{"first_flight":["https://www.youtube.com/watch?v=szskoV8YOyw"]}'::jsonb, true),
  -- WZ-19 (Q27354)
  ('harbin-z-19', 'WZ-19', 'Harbin Aircraft Manufacturing Corporation', 'militaire', 'Le Harbin WZ-19 (ou Z-19) est un hélicoptère de reconnaissance et d''attaque chinois. Le WZ-19 est une version armée du Harbin Z-9W. Il est en quelque sorte le cousin éloigné du Eurocopter AS365 Dauphin. Cet hélicoptère a été développé par HAMC pour équiper l''Armée populaire de libération.', NULL, '2011-01-01', NULL, NULL, NULL, NULL, NULL, NULL, '2012-01-01', NULL, 'République populaire de Chine', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Harbin_Z-19_helicopter.jpg/1280px-Harbin_Z-19_helicopter.jpg', 'Alert5', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:Harbin_Z-19_helicopter.jpg', 'Q27354', 'Harbin Z-19', ARRAY['harbin z-19 black whirlwind', 'wz-19', 'harbin z-19', 'hamc z-19', 'black whirlwind', 'wz19', 'z-19'], 'https://fr.wikipedia.org/wiki/Harbin_WZ-19', '{}'::jsonb, true),
  -- Bell 222 (Q749986)
  ('bell-222-230', 'Bell 222', 'Bell Textron', 'autre', 'Le Bell 222 est un hélicoptère construit par Bell Aircraft Corporation. Il a volé pour la première fois en 1976, et a été certifié en 1979. Il a une masse à vide de 2 066 kg, et une masse maximale de 3 560 kg.', NULL, '1976-08-13', NULL, 10.98, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/7/76/Bell_222a.jpg', 'User:Meggar', 'CC BY-SA 3.0', 'http://creativecommons.org/licenses/by-sa/3.0/', 'https://commons.wikimedia.org/wiki/File:Bell_222a.jpg', 'Q749986', 'Bell 222/230', ARRAY['bell 222', 'bell 222/230', 'bell model 222', 'model 222', '222'], 'https://fr.wikipedia.org/wiki/Bell_222', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Eurocopter UH-72 (Q976985)
  ('eurocopter-uh-72-lakota', 'Eurocopter UH-72', 'Airbus Group, Inc. / Airbus Helicopters', 'militaire', 'L''Eurocopter UH-72 Lakota est un hélicoptère à double turbine équipé d''un rotor principal à quatre pales pour la version UH-72A et cinq pales pour la version UH-72B. L''UH-72 est un dérivé militarisé de l''Eurocopter EC145 et est construit par American Eurocopter, une filiale d''Airbus Group Amérique du Nord à Columbus dans l''État du Mississippi.', NULL, '2006-01-01', NULL, NULL, NULL, NULL, NULL, NULL, '2007-01-01', NULL, NULL, NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/UH-72_Lakota2.jpg/1280px-UH-72_Lakota2.jpg', 'Kim Henry', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:UH-72_Lakota2.jpg', 'Q976985', 'Eurocopter UH-72 Lakota', ARRAY['uh-72 lakota', 'eurocopter uh-72', 'eurocopter uh-72 lakota', 'uh72', 'lakota', 'uh-72a lakota', 'airbus helicopters uh-72 lakota', 'uh-145', 'lakota helicopter', 'airbus uh-72 lakota'], 'https://fr.wikipedia.org/wiki/Eurocopter_UH-72_Lakota', '{}'::jsonb, true),
  -- Kawasaki OH-1 (Q1191374)
  ('kawasaki-oh-1', 'Kawasaki OH-1', 'Kawasaki Heavy Industries / Compagnie aérospatiale Kawasaki', 'militaire', 'Le Kawasaki OH-1 Ninja est un hélicoptère de reconnaissance armée biturbine développé par la firme japonaise Kawasaki Heavy Industries. Il est le premier hélicoptère entièrement développé au Japon. Il supplée au sein des Forces japonaises d''autodéfense l''hélicoptère d''attaque AH-64D et remplace l''OH-6 Cayuse construit sous transfert de technologie par Fuji Heavy Industries. En 2010, seuls 34 OH-1 ont été livrés aux Forces japonaises d''autodéfense.', NULL, '1996-08-06', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Japon', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/JGSDF_OH-1_%2832634%29_in_Camp_Yao.jpg/1280px-JGSDF_OH-1_%2832634%29_in_Camp_Yao.jpg', 'Hunini', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:JGSDF_OH-1_(32634)_in_Camp_Yao.jpg', 'Q1191374', 'Kawasaki OH-1', ARRAY['oh-1 ninja', 'kawasaki oh-1', 'oh1', 'ninja', 'oh-x', 'ohx'], 'https://fr.wikipedia.org/wiki/Kawasaki_OH-1', '{}'::jsonb, true),
  -- AgustaWestland Apache (Q927610)
  ('agustawestland-apache', 'AgustaWestland Apache', 'AgustaWestland / Westland Helicopters', 'militaire', 'L'' AgustaWestland Apache est la version britannique du Boeing AH-64D Apache Longbow. Il est construit sous licence par AgustaWestland (fusionnée avec Leonardo en 2016) pour l''armée britannique. Les 8 premiers hélicoptères ont été construits par Boeing à Mesa (Arizona) tandis que les 59 suivants ont été assemblés par Westland Helicopters à Yeovil (Royaume-Uni) à partir des pièces fournies par Boeing.', NULL, '2000-01-01', NULL, NULL, NULL, NULL, NULL, NULL, '2004-01-01', NULL, 'États-Unis / Royaume-Uni', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Apache_Attack_Helicopter_Takes_Off_from_HMS_Ocean_MOD_45150676.jpg/1280px-Apache_Attack_Helicopter_Takes_Off_from_HMS_Ocean_MOD_45150676.jpg', 'LA(Phot) Bernie Henesy', 'OGL v1.0', 'http://NationalArchives.gov.uk/doc/open-government-licence/version/1/', 'https://commons.wikimedia.org/wiki/File:Apache_Attack_Helicopter_Takes_Off_from_HMS_Ocean_MOD_45150676.jpg', 'Q927610', 'AgustaWestland Apache', ARRAY['apache ah1', 'agustawestland apache', 'westland apache', 'wah-64 apache', 'westland wah-64', 'apache attack helicopter mark 1'], 'https://fr.wikipedia.org/wiki/AgustaWestland_Apache', '{}'::jsonb, true),
  -- HH-65 Dolphin (Q972242)
  ('eurocopter-mh-65-dolphin', 'HH-65 Dolphin', 'Aérospatiale', 'militaire', 'L''Aérospatiale HH-65 Dolphin est un hélicoptère militaire destiné prioritairement aux missions de sauvetage en mer, mais optimisé également pour le soutien opérationnel, notamment dans le cadre de la lutte contre le trafic de stupéfiants, Il est en service dans l''United States Coast Guard. Dérivé profondément modifié du Dauphin 2, il est également connu sous sa désignation constructeur de SA366.', NULL, '1980-01-01', NULL, 11.63, NULL, 3.52, 760, 2290, '1985-01-01', NULL, NULL, NULL, 102, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/USCG_MH-65C_Helicopter_6608_photo_Don_Ramey_Logan.jpg/1280px-USCG_MH-65C_Helicopter_6608_photo_Don_Ramey_Logan.jpg', 'Don Ramey Logan', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'https://commons.wikimedia.org/wiki/File:USCG_MH-65C_Helicopter_6608_photo_Don_Ramey_Logan.jpg', 'Q972242', 'Eurocopter MH-65 Dolphin', ARRAY['aérospatiale h-65 dolphin', 'hh-65 dolphin', 'eurocopter mh-65 dolphin', 'sa366g1', 'hh65', 'dolphin', 'aerospatiale sa 366g1', 'aérospatiale dolphin', 'eurocopter hh-65', 'aerospatiale hh-65', 'sa 366g1', 'airbus hh-65', 'mh65 dolphin', 'h-65 dolphin', 'aérospatiale hh-65 dolphin'], 'https://fr.wikipedia.org/wiki/A%C3%A9rospatiale_HH-65_Dolphin', '{}'::jsonb, true),
  -- Eurocopter EC175 (Q39703)
  ('airbus-helicopters-h175', 'Eurocopter EC175', 'Airbus Helicopters', 'autre', 'L''Airbus Helicopters H175 est un hélicoptère de transport civil de 7 tonnes conçu en partenariat avec des industriels chinois. En Chine, il reçoit la désignation AC352 (anciennement projet Z-15). L''assemblage du premier prototype est achevé et le premier vol a eu lieu le 4 décembre 2009, à 9 heures, sur le site de Marignane.', NULL, '2009-12-17', NULL, NULL, NULL, NULL, NULL, NULL, '2014-12-11', NULL, 'France / République populaire de Chine', NULL, 12, 5, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/F-WWPB_%288970734434%29.jpg/1280px-F-WWPB_%288970734434%29.jpg', 'Tom Andreas Østrem from Jørpeland, Norway', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:F-WWPB_(8970734434).jpg', 'Q39703', 'Airbus Helicopters H175', ARRAY['h175', 'eurocopter ec175', 'airbus helicopters h175', 'airbus helicopters ec175', 'ec175', 'h 175', 'ec 175', 'airbus helicopters h 175', 'ac352', 'eurocopter ec 175', 'eurocopter ec-175', 'ec-175', 'airbus helicopters h-175', 'h-175'], 'https://fr.wikipedia.org/wiki/Airbus_Helicopters_H175', '{}'::jsonb, true),
  -- AgustaWestland AW119 Koala (Q398951)
  ('agustawestland-aw119-koala', 'AgustaWestland AW119 Koala', 'AgustaWestland / Leonardo', 'autre', '119 Koala nommé AgustaWestland AW119 Koala depuis 2016 est un hélicoptère utilitaire civil léger monomoteur.', NULL, '1995-02-01', NULL, 12.92, NULL, 3.6, NULL, NULL, '2000-01-01', NULL, NULL, NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/NYPD_helicopter_N319PD.jpg/1280px-NYPD_helicopter_N319PD.jpg', 'Refueled Dot Net', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:NYPD_helicopter_N319PD.jpg', 'Q398951', 'AgustaWestland AW119 Koala', ARRAY['agustawestland aw119 koala', 'leonardo aw119 koala', 'agusta aw119 koala', 'koala', 'aw 119 koala', 'agusta a119', 'leonardo th-73a', 'h-73', 'a119', 'th-73', 'a.119', 'a 119', 'a-119', 'agusta a.119 koala'], 'https://fr.wikipedia.org/wiki/AgustaWestland_AW119_Koala', '{}'::jsonb, true),
  -- Ka-15 (Q1532201)
  ('kamov-ka-15', 'Ka-15', 'Kamov', 'autre', 'Le Kamov Ka-15 (code OTAN : Hen) était un hélicoptère polyvalent biplace soviétique réalisé par le bureau d''études Kamov. Il fit son premier vol en 1953 et fut utilisé pendant de nombreuses années pour des missions tant civiles que militaires. Le Ka-15 fut le premier type d''hélicoptère de Kamov à être produit en série.', NULL, '1952-01-01', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'AI-14V', 354, 4, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Kamov_Ka-15_Hen_%28ID_unknown%29_%289838722505%29.jpg/1280px-Kamov_Ka-15_Hen_%28ID_unknown%29_%289838722505%29.jpg', 'Alan Wilson', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Kamov_Ka-15_Hen_(ID_unknown)_(9838722505).jpg', 'Q1532201', 'Kamov Ka-15', ARRAY['kamov ka-15', 'ka-15', 'hen'], 'https://fr.wikipedia.org/wiki/Kamov_Ka-15', '{}'::jsonb, true),
  -- Sikorsky CH-54 Tarhe (Q2336788)
  ('sikorsky-ch-54-tarhe', 'Sikorsky CH-54 Tarhe', 'Sikorsky Aircraft Corporation', 'militaire', 'Le S-64 Skycrane, également connu sous la désignation militaire CH-54 Tarhe, est un hélicoptère de transport de type grue volante, construit depuis 1959 par la société Sikorsky Aircraft Corporation. Le nom Skycrane signifie grue volante ; Tarhe signifie grue dans la langue des indiens iroquois Wyandot. Le premier vol a été effectué le 9 mai 1962.', NULL, '1962-01-01', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1990-01-01', NULL, NULL, 105, 4, 'https://upload.wikimedia.org/wikipedia/commons/5/5e/Sikorsky_Skycrane_carrying_parachute_bomb_c.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Sikorsky_Skycrane_carrying_parachute_bomb_c.jpg', 'Q2336788', 'Sikorsky CH-54 Tarhe', ARRAY['sikorsky ch-54 tarhe', 'tarhe', 'sikorsky tarhe', 'tarhe helicopter', 'h-54 tarhe', 'ch54 tarhe', 'sikorsky ch-54'], 'https://fr.wikipedia.org/wiki/Sikorsky_CH-54', '{}'::jsonb, true),
  -- Sikorsky S-61 (Q17163402)
  ('sikorsky-s-61', 'Sikorsky S-61', 'Sikorsky Aircraft Corporation / Mitsubishi', 'autre', 'Le Sikorsky S-61 (nomenclature constructeur), plus connu sous son appellation militaire de SH-3 Sea King est un hélicoptère biturbine de lutte anti-sous-marine et de sauvetage en mer. Il est en service dans l''United States Navy et dans un grand nombre d''autres Forces armées de par le monde. Le Sea King a été construit à 794 exemplaires par Sikorsky entre 1959 et 1980 et sous licence au Royaume-Uni, au Canada, en Italie et au Japon à un total de 679 unités.', NULL, '1959-03-11', NULL, 22.2, NULL, NULL, NULL, NULL, '1961-01-01', NULL, NULL, NULL, 796, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Sikorsky_S-61N_Mk.II.jpg/1280px-Sikorsky_S-61N_Mk.II.jpg', 'Peng Chen', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:Sikorsky_S-61N_Mk.II.jpg', 'Q17163402', 'Sikorsky S-61', ARRAY['s-61', 'sikorsky s-61', 's61', 'sikorsky 61'], 'https://fr.wikipedia.org/wiki/Sikorsky_S-61', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- T-129 ATAK (Q934006)
  ('tai-agustawestland-t129-atak', 'T-129 ATAK', 'Turkish Aerospace Industries', 'militaire', '129 International, développé avec le transfert de technologie par Turkish Aerospace Industries (TAI), détentrice de tous les droits liés à la propriété intellectuelle, pour le compte de l''Armée de terre turque.', NULL, '2011-08-17', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Turquie / Italie', NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/a/a8/TAI%2C_P2%2C_T-129A_ATAK_%2844235030172%29.jpg', 'Anna Zvereva from Tallinn, Estonia', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 'https://commons.wikimedia.org/wiki/File:TAI,_P2,_T-129A_ATAK_(44235030172).jpg', 'Q934006', 'TAI/AgustaWestland T129 ATAK', ARRAY['tai/leonardo t129 atak', 't-129 atak', 't129 atak', 'tai/agustawestland t129 atak', 'tai t129', 'tai/agustawestland t129', 'atak', 'tai-agustawestland t129 atak', 'tai t-129 atak', 'tai atak', 'tai/agustawestland t-129 atak'], 'https://fr.wikipedia.org/wiki/TAI_T-129_ATAK', '{"first_flight":["https://www.tai.com.tr/haber/tusasin-urettigi-t129-helikopteri-ilk-ucusunu-basariyla-gerceklestirdi"]}'::jsonb, true),
  -- Airbus Helicopters H160 (Q19412818)
  ('airbus-helicopters-h160', 'Airbus Helicopters H160', 'Airbus Helicopters', 'autre', 'L''Airbus Helicopters H160, désigné par le nom de code X4 pendant ses premières phases d''études, est un hélicoptère développé par le constructeur européen Airbus Helicopters. Il effectue son premier vol le 13 juin 2015 et obtient sa certification par l''Agence européenne de la sécurité aérienne le 1er juillet 2020. La première livraison - à la société All Nippon Helicopter (ANH) - a eu lieu en 2021, l''entrée en service opérationnel se faisant en 2022.', NULL, '2015-06-13', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'France', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Airbus_Helicopters_H160_%28cropped%29.jpg/1280px-Airbus_Helicopters_H160_%28cropped%29.jpg', 'Berg2', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'https://commons.wikimedia.org/wiki/File:Airbus_Helicopters_H160_(cropped).jpg', 'Q19412818', 'Airbus Helicopters H160', ARRAY['airbus helicopters h160', 'h160', 'airbus h160', 'x4', 'h 160'], 'https://fr.wikipedia.org/wiki/Airbus_Helicopters_H160', '{}'::jsonb, true)
