  -- Hiller UH-12 (Q691806)
  ('hiller-oh-23-raven', 'Hiller UH-12', 'Hiller Aircraft', 'militaire', 'Le Hiller UH-12 Raven est un hélicoptère militaire polyvalent américain des années 1950. L''UH-12 était connu dans l''US Army sous la désignation de H-23.', NULL, '1948-01-01', NULL, 8.45, NULL, 3, 217, NULL, NULL, NULL, 'États-Unis', NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/5/54/OH-23_inflight_colour_photo.jpg', 'U.S. Army', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:OH-23_inflight_colour_photo.jpg', 'Q691806', 'Hiller OH-23 Raven', ARRAY['uh-12', 'hiller uh-12', 'hiller oh-23 raven', 'hiller h-23 raven', 'oh23 raven', 'hiller 360', 'united helicopters uh-12', 'raven', 'oh-23 raven', 'rogerson hiller uh-12', 'h-23 raven', 'hiller uh-12 raven'], 'https://fr.wikipedia.org/wiki/Hiller_UH-12_Raven', '{}'::jsonb, true),
  -- PZL W-3 (Q764207)
  ('pzl-w-3-soko', 'PZL W-3', 'Państwowe Zakłady Lotnicze', 'autre', 'Le PZL W-3 Sokół est un hélicoptère bimoteur, polyvalent et de taille moyenne fabriqué en Pologne par PZL-Świdnik.', NULL, '1979-11-16', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/W-3_Sok%C3%B3%C5%82.jpg/1280px-W-3_Sok%C3%B3%C5%82.jpg', 'No machine-readable author provided. Voytek S assumed (based on copyright claims).', 'CC BY 2.5', 'https://creativecommons.org/licenses/by/2.5', 'https://commons.wikimedia.org/wiki/File:W-3_Sok%C3%B3%C5%82.jpg', 'Q764207', 'PZL W-3 Sokół', ARRAY['w-3 sokół', 'pzl w-3', 'pzl w-3 sokół', 'w3', 'sokol', 'sokół', 'pzl-świdnik w-3 sokol', 'pzl w-3a sokół (vojenský vrtulník)'], 'https://fr.wikipedia.org/wiki/PZL_W-3', '{}'::jsonb, true),
  -- Sikorsky S-70 (Q1150702)
  ('sikorsky-s-70', 'Sikorsky S-70', 'Inconnu', 'autre', 'Produit par la Sikorsky Aircraft Corporation depuis 1974, les S-70A, B, et C sont les versions export des UH-60 Black Hawk et SH-60 Seahawk. Il est produit depuis les années 2010 sous licence par PZL Mielec en Pologne.', NULL, '1974-01-01', NULL, 15.26, NULL, NULL, NULL, NULL, NULL, NULL, 'États-Unis', NULL, NULL, 3, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Colorado_Division_of_Fire_Prevention_and_Control_S-70i_Firehawk.jpg/1280px-Colorado_Division_of_Fire_Prevention_and_Control_S-70i_Firehawk.jpg', 'Benjamin Cossel', 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Colorado_Division_of_Fire_Prevention_and_Control_S-70i_Firehawk.jpg', 'Q1150702', 'Sikorsky S-70', ARRAY['s-70', 'sikorsky s-70', 'm46', 'black hawk', 's70', 'sikorsky 70', 'sikorsky s-70a/b'], 'https://fr.wikipedia.org/wiki/Sikorsky_S-70', '{"length_m":["https://www.wikidata.org/wiki/Q29042798"]}'::jsonb, true),
  -- Kazan Ansat (Q1416341)
