  -- Lockheed AH-56 Cheyenne (Q432484)
  ('lockheed-ah-56-cheyenne', 'Lockheed AH-56 Cheyenne', 'Lockheed', 'militaire', 'Le Lockheed AH-56 Cheyenne était un programme d''hélicoptère d''attaque, destiné à prendre la relève du Bell AH-1 Cobra, dont on mesurait les déficiences en termes de puissance de feu, de survivabilité et de vitesse. L''AH-56 est un appareil intéressant, hybride entre un hélicoptère et un aéronef à voilure fixe.', NULL, '1967-09-21', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'États-Unis', NULL, 10, 5, 'https://upload.wikimedia.org/wikipedia/commons/d/d3/Ah56a-lc1_b.jpg', NULL, 'Public domain', NULL, 'https://commons.wikimedia.org/wiki/File:Ah56a-lc1_b.jpg', 'Q432484', 'Lockheed AH-56 Cheyenne', ARRAY['lockheed ah-56 cheyenne', 'cheyenne helicopter', 'lockheed cheyenne', 'ah56 cheyenne', 'h-56 cheyenne', 'ah-56 cheyenne'], 'https://fr.wikipedia.org/wiki/Lockheed_AH-56_Cheyenne', '{}'::jsonb, true),
