  ('sikorsky-s-97-raider', 'Sikorsky S-97 Raider', 'Sikorsky Aircraft Corporation', 'militaire', 'Le Sikorsky S-97 Raider est un hélicoptère américain doté d''un rotor contrarotatif et d''une hélice propulsive. Dérivé de l''hélicoptère expérimental Sikorsky X2, il est développé comme appareil expérimental pour le Sikorsky Raider X qui devait être construit en série.', NULL, '2015-05-22', NULL, 11, NULL, NULL, 570, NULL, NULL, NULL, 'États-Unis', NULL, NULL, 3, 'https://upload.wikimedia.org/wikipedia/commons/a/a1/Sikorsky_S-97_Raider_RFront_MacDill_AirFest_5Oct2011_%2814512968740%29.jpg', 'Valder137', 'CC BY 2.0', 'https://creativecommons.org/licenses/by/2.0', 'https://commons.wikimedia.org/wiki/File:Sikorsky_S-97_Raider_RFront_MacDill_AirFest_5Oct2011_(14512968740).jpg', 'Q1142731', 'Sikorsky S-97 Raider', ARRAY['sikorsky s-97 raider', 's-97 raider', 'sikorsky raider', 'raider'], 'https://fr.wikipedia.org/wiki/Sikorsky_S-97_Raider', '{}'::jsonb, true),
